#!/usr/bin/env python3
"""q.py [-m] [-b] [-f in.bimcraft] cmds.txt
Each line of cmds.txt: commands joined by ' ;; '. For each line, runs the original (or mine with -m;
both with -b) in a fresh dir on the input file, saves, and prints the replies (last N), the error, and
the elements of the saved file that are new or changed relative to the input file (and changed
top-level sections except next_id)."""
import json, os, subprocess, sys, tempfile, shutil, re
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-aed8172cff8d68ba7/target/release/bimcraft-cli')
G = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
a = sys.argv[1:]
exes = [ORIG]
infile = None
both = False
allout = False
while a:
    if a[0] == '-m': exes = [MINE]; a = a[1:]
    elif a[0] == '-b': exes = [ORIG, MINE]; both = True; a = a[1:]
    elif a[0] == '-f': infile = a[1]; a = a[2:]
    elif a[0] == '-a': allout = True; a = a[1:]
    else: break
lines = [l.rstrip('\n') for l in open(a[0]) if l.strip() and not l.startswith('#')]
base = None
if infile:
    base = json.load(open(infile))
else:
    base = json.load(open('/tmp/views-tools/new.bimcraft'))
def run(exe, l):
    d = tempfile.mkdtemp(prefix='q', dir='/tmp/views-a/scratch')
    args = [exe, 'run']
    if infile:
        shutil.copy(infile, d)
        args.append(os.path.basename(infile))
    cmds = l.split(' ;; ')
    for c in cmds:
        args += ['--cmd', c]
    args += ['--save', 'zz_out.bimcraft']
    p = subprocess.run(args, cwd=d, capture_output=True, timeout=120)
    out = p.stdout.decode('utf-8', 'replace').strip().split('\n')
    if infile and not allout:
        out = out[1:]
    out = [x for x in out if x and not x.startswith('{"format":"bimcraft","path":"zz_out')]
    res = []
    for o in out:
        res.append('OUT ' + o)
    if p.stderr:
        res.append('ERR ' + p.stderr.decode('utf-8', 'replace').strip())
    fn = os.path.join(d, 'zz_out.bimcraft')
    if os.path.exists(fn):
        dd = json.load(open(fn))
        bel = base.get('elements', {})
        for id, e in dd.get('elements', {}).items():
            if id not in bel:
                res.append('  + %s %s' % (id, json.dumps(e, ensure_ascii=False)))
            elif G.sub('G', json.dumps(bel[id])) != G.sub('G', json.dumps(e)):
                res.append('  ~ %s %s' % (id, json.dumps(e, ensure_ascii=False)))
        for id in bel:
            if id not in dd.get('elements', {}):
                res.append('  - %s' % id)
        for k, v in dd.items():
            if k in ('elements', 'library', 'uid', 'next_id'):
                continue
            if k not in base or G.sub('G', json.dumps(base[k])) != G.sub('G', json.dumps(v)):
                res.append('  top %s %s' % (k, json.dumps(v, ensure_ascii=False)[:2000]))
        for k in base:
            if k not in dd:
                res.append('  top-gone %s' % k)
        bl = {(e['kind'], e['name']) for e in base.get('library', {}).values()}
        for id, e in dd.get('library', {}).items():
            if (e['kind'], e['name']) not in bl:
                res.append('  lib %s %s' % (id, json.dumps(e, ensure_ascii=False)))
    shutil.rmtree(d)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return G.sub(rep, '\n'.join(res)) + ' [%d]' % p.returncode
os.makedirs('/tmp/views-a/scratch', exist_ok=True)
same = 0
for l in lines:
    outs = [run(e, l) for e in exes]
    if both:
        if outs[0] == outs[1]:
            same += 1
            print('SAME', l[:160])
        else:
            print('DIFF', l)
            print('  orig:', outs[0].replace('\n', '\n        '))
            print('  mine:', outs[1].replace('\n', '\n        '))
    else:
        print('>>', l)
        print('  ', outs[0].replace('\n', '\n   '))
if both:
    print('%d/%d same' % (same, len(lines)))

