//! What the views show, as far as their frames go: the walls' outlines in plan with their corners
//! mitred, the solids the model builds (an outline in plan between two heights), the box round the
//! walls and floors the building elevations look at, what a plan shows (`crop` without a region and
//! a plan's viewport), a section's or an elevation's frame along its line and up, and how big the
//! 3D view's picture of the model is.

use super::super::common::*;
use super::super::model::{self as m, WallLine};
use crate::project::Project;

/// A box in plan: its south-west and north-east corners.
pub type BBox = ([f64; 2], [f64; 2]);

/// Takes a point into a box.
pub fn grow(b: &mut Option<BBox>, p: [f64; 2]) {
    match b {
        None => *b = Some((p, p)),
        Some((lo, hi)) => {
            lo[0] = lo[0].min(p[0]);
            lo[1] = lo[1].min(p[1]);
            hi[0] = hi[0].max(p[0]);
            hi[1] = hi[1].max(p[1]);
        }
    }
}

/// Takes points into a box.
pub fn grow_all(b: &mut Option<BBox>, pts: &[[f64; 2]]) {
    for p in pts {
        grow(b, *p);
    }
}

// ---------------------------------------------------------------- walls joined

#[derive(Clone)]
struct WallShape {
    id: u64,
    level: String,
    /// The location line (where its points are, where walls meet).
    loc: WallLine,
    centre: WallLine,
    thick: f64,
    /// Left and right faces from its start to its end.
    left: Vec<[f64; 2]>,
    right: Vec<[f64; 2]>,
}

/// The number of chords an arc of radius `r` turning `sweep` radians is drawn with: none further
/// than a millimetre from it.
pub fn arc_segments(r: f64, sweep: f64) -> usize {
    let r = r.abs();
    if r <= 0.5 {
        return 1;
    }
    let step = 2.0 * (1.0 - 1.0 / r).acos();
    if !(step > 0.0) {
        return 1;
    }
    let n = (sweep.abs() / step).ceil();
    if n < 1.0 {
        1
    } else if n > 100_000.0 {
        100_000
    } else {
        n as usize
    }
}

/// Points along a wall line: its two ends, or an arc's chords.
fn line_points(l: &WallLine, segments: usize) -> Vec<[f64; 2]> {
    if !l.is_arc() {
        return vec![l.start, l.end];
    }
    l.points(segments.max(1))
}

fn wall_shapes(pr: &Project) -> Vec<WallShape> {
    let mut out = Vec::new();
    for (id, e) in &pr.elements {
        if cat(e) != "wall" {
            continue;
        }
        let loc = m::location_line(e);
        let centre = m::centre_line(pr, e);
        let t = m::wall_thickness(pr, e);
        let n = match centre.circle() {
            Some((_, r)) => arc_segments(r, centre.arc.to_radians()),
            None => 1,
        };
        let l = centre.offset(t / 2.0);
        let r = centre.offset(-t / 2.0);
        out.push(WallShape {
            id: *id,
            level: s_of(e, "level").unwrap_or("").to_string(),
            loc,
            centre,
            thick: t,
            left: line_points(&l, n),
            right: line_points(&r, n),
        });
    }
    out
}

fn same_point(a: [f64; 2], b: [f64; 2]) -> bool {
    (a[0] - b[0]).abs() < 1e-6 && (a[1] - b[1]).abs() < 1e-6
}

/// Where the lines through a, a + da and through b, b + db cross.
fn cross_lines(a: [f64; 2], da: [f64; 2], b: [f64; 2], db: [f64; 2]) -> Option<[f64; 2]> {
    let den = m::cross(da, db);
    if den.abs() < 1e-12 {
        return None;
    }
    let t = m::cross(m::sub(b, a), db) / den;
    Some(m::add(a, m::mul(da, t)))
}

/// Mitres two straight walls meeting end to end at one point, where the mitre stays within a
/// wall's thickness of the end of each.
fn mitre(ws: &mut [WallShape], (i, at_start_i): (usize, bool), (j, at_start_j): (usize, bool)) {
    let dir = |w: &WallShape| m::unit(m::sub(w.centre.end, w.centre.start));
    let (a, b) = (&ws[i], &ws[j]);
    let da = if at_start_i { dir(a) } else { m::mul(dir(a), -1.0) };
    let db = if at_start_j { dir(b) } else { m::mul(dir(b), -1.0) };
    if m::cross(da, db).abs() < 1e-9 {
        return;
    }
    // the faces of each to the left and to the right of the way it leaves the corner
    let face = |w: &WallShape, at_start: bool, left_of_away: bool| -> ([f64; 2], [f64; 2]) {
        // leaving from its start the way runs start to end, so its own left face is left of it
        let own_left = left_of_away == at_start;
        let f = if own_left { &w.left } else { &w.right };
        (f[0], m::sub(f[f.len() - 1], f[0]))
    };
    let (al, ald) = face(a, at_start_i, true);
    let (ar, ard) = face(a, at_start_i, false);
    let (bl, bld) = face(b, at_start_j, true);
    let (br, brd) = face(b, at_start_j, false);
    let (Some(m1), Some(m2)) = (cross_lines(al, ald, br, brd), cross_lines(ar, ard, bl, bld)) else { return };
    let end_of = |w: &WallShape, at_start: bool| if at_start { w.centre.start } else { w.centre.end };
    let beyond = |w: &WallShape, at_start: bool, d: [f64; 2], p: [f64; 2]| -m::dot(m::sub(p, end_of(w, at_start)), d);
    let ok = |w: &WallShape, at_start: bool, d: [f64; 2]| {
        beyond(w, at_start, d, m1) < w.thick && beyond(w, at_start, d, m2) < w.thick
    };
    if !ok(a, at_start_i, da) || !ok(b, at_start_j, db) {
        return;
    }
    let set = |w: &mut WallShape, at_start: bool, left_of_away: bool, p: [f64; 2]| {
        let own_left = left_of_away == at_start;
        let f = if own_left { &mut w.left } else { &mut w.right };
        let k = if at_start { 0 } else { f.len() - 1 };
        f[k] = p;
    };
    set(&mut ws[i], at_start_i, true, m1);
    set(&mut ws[i], at_start_i, false, m2);
    set(&mut ws[j], at_start_j, false, m1);
    set(&mut ws[j], at_start_j, true, m2);
}

/// Each wall's outline in plan (its faces, mitred where two straight walls of a level meet end
/// to end), by id.
pub fn wall_outlines(pr: &Project) -> Vec<(u64, Vec<[f64; 2]>)> {
    let mut ws = wall_shapes(pr);
    // the ends that meet
    let mut ends: Vec<(usize, bool, [f64; 2])> = Vec::new();
    for (i, w) in ws.iter().enumerate() {
        if w.centre.is_arc() {
            continue;
        }
        ends.push((i, true, w.loc.start));
        ends.push((i, false, w.loc.end));
    }
    let mut done = vec![false; ends.len()];
    for k in 0..ends.len() {
        if done[k] {
            continue;
        }
        let group: Vec<usize> = (k..ends.len())
            .filter(|&q| !done[q] && same_point(ends[q].2, ends[k].2) && ws[ends[q].0].level == ws[ends[k].0].level)
            .collect();
        for &q in &group {
            done[q] = true;
        }
        if group.len() == 2 && ends[group[0]].0 != ends[group[1]].0 {
            let (i, si, _) = ends[group[0]];
            let (j, sj, _) = ends[group[1]];
            mitre(&mut ws, (i, si), (j, sj));
        }
    }
    ws.into_iter()
        .map(|w| {
            let mut pts = w.left.clone();
            let mut back = w.right.clone();
            back.reverse();
            pts.extend(back);
            (w.id, pts)
        })
        .collect()
}

// ---------------------------------------------------------------- solids

/// What the model builds, as far as a frame goes: an outline in plan between two heights.
#[derive(Clone, Debug)]
pub struct Solid {
    pub id: u64,
    pub cat: String,
    pub pts: Vec<[f64; 2]>,
    pub z0: f64,
    pub z1: f64,
}

fn type_thickness(pr: &Project, cat: &str, e: &crate::json::Value, dflt: f64) -> f64 {
    m::type_entry(pr, cat, e).and_then(|t| f_of(t, "thickness")).unwrap_or(dflt)
}

/// The largest distance from an outline's edges to a point inside it, near enough for a hipped
/// roof's ridge: half the shorter side of its box.
fn ridge_run(pts: &[[f64; 2]]) -> f64 {
    match m::bounds(pts) {
        Some((lo, hi)) => ((hi[0] - lo[0]).min(hi[1] - lo[1]) / 2.0).max(0.0),
        None => 0.0,
    }
}

/// An outline grown `d` out all round (a roof's overhang), as its box grown.
fn grown(pts: &[[f64; 2]], d: f64) -> Vec<[f64; 2]> {
    if d == 0.0 {
        return pts.to_vec();
    }
    match m::bounds(pts) {
        Some((lo, hi)) => vec![[lo[0] - d, lo[1] - d], [hi[0] + d, lo[1] - d], [hi[0] + d, hi[1] + d], [lo[0] - d, hi[1] + d]],
        None => Vec::new(),
    }
}

/// Every solid the model builds: walls (joined), floors, ceilings, roofs, columns, footings.
pub fn solids(pr: &Project) -> Vec<Solid> {
    let mut out = Vec::new();
    for (id, pts) in wall_outlines(pr) {
        let e = pr.el(id).unwrap();
        let (z0, z1) = m::base_top(pr, e);
        out.push(Solid { id, cat: "wall".into(), pts, z0, z1 });
    }
    for (id, e) in &pr.elements {
        let c = cat(e);
        let lv = m::level_elevation(pr, e, "level").unwrap_or(0.0);
        match c {
            "floor" => {
                let Some(pts) = pts_of(e, "boundary") else { continue };
                let t = type_thickness(pr, "floor", e, 200.0);
                let top = lv + f_of(e, "offset").unwrap_or(0.0);
                let mut rise = 0.0;
                if let (Some(s), Some(a)) = (f_of(e, "slope"), pts_of(e, "arrow")) {
                    if a.len() == 2 {
                        let d = m::unit(m::sub(a[1], a[0]));
                        let far = pts.iter().map(|p| m::dot(m::sub(*p, a[0]), d)).fold(f64::MIN, f64::max);
                        let near = pts.iter().map(|p| m::dot(m::sub(*p, a[0]), d)).fold(f64::MAX, f64::min);
                        let k = s.to_radians().tan();
                        rise = (far * k).max(near * k).max(0.0);
                        let fall = (far * k).min(near * k).min(0.0);
                        out.push(Solid { id: *id, cat: c.into(), pts: pts.clone(), z0: top + fall - t, z1: top + rise });
                        continue;
                    }
                }
                out.push(Solid { id: *id, cat: c.into(), pts, z0: top - t, z1: top + rise });
            }
            "ceiling" => {
                let Some(pts) = pts_of(e, "boundary") else { continue };
                let t = type_thickness(pr, "ceiling", e, 20.0);
                let under = lv + f_of(e, "offset").unwrap_or(2600.0);
                out.push(Solid { id: *id, cat: c.into(), pts, z0: under, z1: under + t });
            }
            "roof" => {
                let Some(b) = pts_of(e, "boundary") else { continue };
                let t = type_thickness(pr, "roof", e, 300.0);
                let base = lv + f_of(e, "offset").unwrap_or(0.0);
                let over = f_of(e, "overhang").unwrap_or(0.0);
                let pts = grown(&b, over);
                let slope = f_of(e, "slope").unwrap_or(30.0);
                let top = if slope.abs() < 1e-9 {
                    base + t
                } else {
                    let a = slope.to_radians();
                    base + ridge_run(&pts) * a.tan() + t / a.cos()
                };
                out.push(Solid { id: *id, cat: c.into(), pts, z0: base, z1: top });
            }
            "column" | "structuralcolumn" | "structural_column" | "footing" => {
                let Some(pts) = m::outline(pr, *id) else { continue };
                let (z0, z1) = if c == "footing" {
                    let t = m::type_entry(pr, "footing", e).and_then(|t| f_of(t, "thickness")).unwrap_or(500.0);
                    let top = lv + f_of(e, "offset").unwrap_or(0.0);
                    (top - t, top)
                } else {
                    m::base_top(pr, e)
                };
                out.push(Solid { id: *id, cat: c.into(), pts, z0, z1 });
            }
            _ => {}
        }
    }
    out
}

/// The categories a view's graphics hide.
fn hidden_categories(pr: &Project, view: u64) -> Vec<String> {
    let mut out = Vec::new();
    let Some(e) = pr.el(view) else { return out };
    if let Some(g) = e.get("graphics").and_then(|g| g.get("categories")).and_then(|c| c.as_obj()) {
        for (k, v) in g.iter() {
            if v.get("hidden").and_then(|h| h.as_bool()) == Some(true) {
                out.push(k.clone());
            }
        }
    }
    out
}

fn shown(hidden: &[String], cat: &str) -> bool {
    let c = match cat {
        "structuralcolumn" => "structural_column",
        x => x,
    };
    !hidden.iter().any(|h| h == c || h == cat)
}

// ---------------------------------------------------------------- the box the elevations look at

/// The box round the walls and floors in plan, which the building elevations stand round.
pub fn walls_and_floors_box(pr: &Project) -> Option<BBox> {
    let mut b = None;
    for (_, pts) in wall_outlines(pr) {
        grow_all(&mut b, &pts);
    }
    for e in pr.elements.values() {
        if cat(e) == "floor" {
            if let Some(pts) = pts_of(e, "boundary") {
                grow_all(&mut b, &pts);
            }
        }
    }
    b
}

/// The box round everything the model builds, in plan.
pub fn model_box(pr: &Project) -> Option<BBox> {
    let mut b = None;
    for s in solids(pr) {
        grow_all(&mut b, &s.pts);
    }
    b
}

/// A level's rectangle in plan: its own extent, else the model's a metre past it (a 20 m square
/// round the origin when there is no model).
pub fn level_rect(pr: &Project, level: &crate::json::Value, model: Option<BBox>) -> BBox {
    if let Some(a) = level.get("extent").and_then(|x| x.as_arr()) {
        if a.len() == 2 {
            if let (Some(p), Some(q)) = (crate::commands::params::point_of(&a[0]), crate::commands::params::point_of(&a[1])) {
                return (p, q);
            }
        }
    }
    match model {
        Some((lo, hi)) => ([lo[0] - 1000.0, lo[1] - 1000.0], [hi[0] + 1000.0, hi[1] + 1000.0]),
        None => ([-10000.0, -10000.0], [10000.0, 10000.0]),
    }
}

// ---------------------------------------------------------------- sections and elevations

/// A section's or an elevation's line: start, unit direction along it, length, and the way it
/// looks (left of the line).
pub fn view_line(e: &crate::json::Value) -> ([f64; 2], [f64; 2], f64, [f64; 2]) {
    let s = pt_of(e, "start").unwrap_or([0.0, 0.0]);
    let t = pt_of(e, "end").unwrap_or([0.0, 0.0]);
    let len = m::dist(s, t);
    let d = m::unit(m::sub(t, s));
    (s, d, len, [-d[1], d[0]])
}

/// The heights a section frames before its margins: its levels and what the model builds.
fn heights(pr: &Project, sol: &[Solid]) -> Option<(f64, f64)> {
    let mut lo = f64::INFINITY;
    let mut hi = f64::NEG_INFINITY;
    for id in crate::model::levels(pr) {
        let z = crate::model::elev(pr, id);
        lo = lo.min(z);
        hi = hi.max(z);
    }
    for s in sol {
        lo = lo.min(s.z0);
        hi = hi.max(s.z1);
    }
    if lo.is_finite() {
        Some((lo, hi))
    } else {
        None
    }
}

/// A section's or an elevation's frame: along its line from its start (`u`) and up (`v`), the
/// model (and its levels where it sees them) and the line itself, 600 mm over and under; a
/// cropped one its line and its crop, 600 mm over and under.
pub fn section_frame(pr: &Project, id: u64) -> (f64, f64, f64, f64) {
    let e = pr.el(id).unwrap();
    let (s, d, len, look) = view_line(e);
    if let Some(c) = e.get("crop").and_then(|c| c.as_arr()) {
        if c.len() == 2 {
            let b = c[0].as_f64().unwrap_or(0.0);
            let t = c[1].as_f64().unwrap_or(0.0);
            return (0.0, len, b - 600.0, t + 600.0);
        }
    }
    let hidden = hidden_categories(pr, id);
    let all = solids(pr);
    let sol: Vec<Solid> = all.iter().filter(|x| shown(&hidden, &x.cat)).cloned().collect();
    let mut u0 = 0.0f64;
    let mut u1 = len;
    for x in &sol {
        for p in &x.pts {
            let u = m::dot(m::sub(*p, s), d);
            u0 = u0.min(u);
            u1 = u1.max(u);
        }
    }
    let depth = f_of(e, "depth");
    let mb = {
        let mut b = None;
        for x in &all {
            grow_all(&mut b, &x.pts);
        }
        b
    };
    if shown(&hidden, "level") {
        for lid in crate::model::levels(pr) {
            let le = pr.el(lid).unwrap();
            let (lo, hi) = level_rect(pr, le, mb);
            let corners = [lo, [hi[0], lo[1]], hi, [lo[0], hi[1]]];
            let ss: Vec<f64> = corners.iter().map(|p| m::dot(m::sub(*p, s), look)).collect();
            let smax = ss.iter().cloned().fold(f64::MIN, f64::max);
            let smin = ss.iter().cloned().fold(f64::MAX, f64::min);
            let seen = smax >= -1.0 && depth.map_or(true, |dp| smin <= dp);
            if !seen {
                continue;
            }
            for p in corners {
                let u = m::dot(m::sub(p, s), d);
                u0 = u0.min(u);
                u1 = u1.max(u);
            }
        }
    }
    let (z0, z1) = heights(pr, &sol).unwrap_or((0.0, 0.0));
    (u0, u1, z0 - 600.0, z1 + 600.0)
}

// ---------------------------------------------------------------- plans

/// The view range of a plan (its own, or its parent's for a dependent one): cut, bottom, depth.
fn view_range(pr: &Project, view: u64) -> (f64, f64, f64) {
    let mut e = pr.el(view);
    if let Some(x) = e {
        if let Some(p) = ref_id(pr, x, "parent") {
            e = pr.el(p);
        }
    }
    let vr = e.and_then(|x| x.get("view_range"));
    let g = |k: &str, d: f64| vr.and_then(|v| f_of(v, k)).unwrap_or(d);
    (g("cut", 1200.0), g("bottom", 0.0), g("depth", 0.0))
}

/// The GUIDs annotation is in when it is drawn in this plan: the plan's own (and a dependent's
/// parent's), and the level's own plan where annotation names no view.
fn plan_annotation_views(pr: &Project, view: u64) -> Vec<String> {
    let mut out = vec![guid(pr, view)];
    if let Some(e) = pr.el(view) {
        if let Some(p) = s_of(e, "parent") {
            out.push(p.to_string());
        }
    }
    out
}

/// Whether an element of annotation is drawn in a plan.
pub fn annotation_in_plan(pr: &Project, view: u64, e: &crate::json::Value) -> bool {
    let views = plan_annotation_views(pr, view);
    if let Some(v) = s_of(e, "view") {
        return views.iter().any(|g| g == v);
    }
    // no view: a dimension on its level's own plan, a tag on its host's
    let Some(level) = plan_level(pr, view) else { return false };
    if cat_of(pr, view) != "level" {
        // a plan view shows its own annotation, and a dependent its parent's
        let lg = guid(pr, level);
        let parent_is_level = pr.el(view).and_then(|x| s_of(x, "parent")) == Some(lg.as_str());
        if !parent_is_level {
            return false;
        }
    }
    let lg = guid(pr, level);
    match cat(e) {
        "dimension" => s_of(e, "level") == Some(lg.as_str()),
        "tag" => host_level(pr, e).as_deref() == Some(lg.as_str()),
        _ => false,
    }
}

/// The level GUID a tag's host stands on (a door's or window's through its wall).
pub fn host_level(pr: &Project, e: &crate::json::Value) -> Option<String> {
    let h = ref_id(pr, e, "host")?;
    let he = pr.el(h)?;
    if let Some(l) = s_of(he, "level") {
        return Some(l.to_string());
    }
    let w = ref_id(pr, he, "host")?;
    s_of(pr.el(w)?, "level").map(|s| s.to_string())
}

/// The points a piece of annotation stands at in its view.
fn annotation_points(e: &crate::json::Value) -> Vec<[f64; 2]> {
    let mut out = Vec::new();
    match cat(e) {
        "text" | "spot" | "detailgroup" => {
            if let Some(p) = pt_of(e, "at") {
                out.push(p);
            }
            if let Some(p) = pt_of(e, "leader") {
                out.push(p);
            }
        }
        "dimension" => {
            if let Some(p) = pt_of(e, "at") {
                out.push(p);
            }
        }
        "line" => {
            for k in ["start", "end", "through", "centre"] {
                if let Some(p) = pt_of(e, k) {
                    out.push(p);
                }
            }
            for k in ["points", "control", "fit"] {
                if let Some(ps) = pts_of(e, k) {
                    out.extend(ps);
                }
            }
        }
        "region" => {
            if let Some(a) = e.get("sketch").and_then(|s| s.as_arr()) {
                for l in a {
                    for k in ["start", "end"] {
                        if let Some(p) = pt_of(l, k) {
                            out.push(p);
                        }
                    }
                }
            }
        }
        "repeatingdetail" => {
            for k in ["start", "end"] {
                if let Some(p) = pt_of(e, k) {
                    out.push(p);
                }
            }
        }
        _ => {}
    }
    out
}

/// What a plan shows, in plan: the model it cuts or sees, roofs over it, the sections', the
/// elevations' and the grids' lines, and its annotation. None where it shows nothing.
pub fn plan_shows(pr: &Project, view: u64) -> Option<BBox> {
    let level = plan_level(pr, view)?;
    let z = crate::model::elev(pr, level);
    let (cut, bottom, depth) = view_range(pr, view);
    let low = z + bottom.min(depth).min(bottom);
    let cut_at = z + cut;
    let hidden = hidden_categories(pr, view);
    let mut b = None;
    for s in solids(pr) {
        if !shown(&hidden, &s.cat) {
            continue;
        }
        let show = match s.cat.as_str() {
            "roof" => s.z1 > low,
            "floor" | "ceiling" => s.z1 >= low && s.z1 <= cut_at.max(low) || (s.z0 < cut_at && s.z1 > cut_at),
            _ => s.z0 < cut_at && s.z1 > low,
        };
        if show {
            grow_all(&mut b, &s.pts);
        }
    }
    for e in pr.elements.values() {
        match cat(e) {
            "section" | "elevation" => {
                if !shown(&hidden, cat(e)) {
                    continue;
                }
                for k in ["start", "end"] {
                    if let Some(p) = pt_of(e, k) {
                        grow(&mut b, p);
                    }
                }
            }
            "grid" => {
                if !shown(&hidden, "grid") {
                    continue;
                }
                for k in ["start", "end"] {
                    if let Some(p) = pt_of(e, k) {
                        grow(&mut b, p);
                    }
                }
            }
            "text" | "spot" | "dimension" | "line" | "region" | "detailgroup" | "repeatingdetail" => {
                if annotation_in_plan(pr, view, e) {
                    grow_all(&mut b, &annotation_points(e));
                }
            }
            _ => {}
        }
    }
    b
}

/// A plan's crop (its own; a dependent's own too), if it has one.
pub fn plan_crop(e: &crate::json::Value) -> Option<BBox> {
    let a = e.get("crop")?.as_arr()?;
    if a.len() != 2 {
        return None;
    }
    let p = pt_of_v(&a[0])?;
    let q = pt_of_v(&a[1])?;
    Some((p, q))
}

fn pt_of_v(v: &crate::json::Value) -> Option<[f64; 2]> {
    let a = v.as_arr()?;
    if a.len() < 2 {
        return None;
    }
    Some([a[0].as_f64()?, a[1].as_f64()?])
}

// ---------------------------------------------------------------- the 3D view

/// How wide and tall (model mm) the 3D view's parallel picture of the model is, seen from
/// `azimuth` degrees round from east and `elevation` degrees up. None for an empty model.
pub fn view3d_extent(pr: &Project, view: Option<u64>, azimuth: f64, elevation: f64) -> Option<(f64, f64)> {
    let hidden = view.map(|v| hidden_categories(pr, v)).unwrap_or_default();
    let (a, e) = (azimuth.to_radians(), elevation.to_radians());
    let r = [-a.sin(), a.cos(), 0.0];
    let u = [-e.sin() * a.cos(), -e.sin() * a.sin(), e.cos()];
    let mut xs = (f64::INFINITY, f64::NEG_INFINITY);
    let mut ys = (f64::INFINITY, f64::NEG_INFINITY);
    let mut any = false;
    for s in solids(pr) {
        if !shown(&hidden, &s.cat) {
            continue;
        }
        for p in &s.pts {
            for z in [s.z0, s.z1] {
                let x = p[0] * r[0] + p[1] * r[1];
                let y = p[0] * u[0] + p[1] * u[1] + z * u[2];
                xs = (xs.0.min(x), xs.1.max(x));
                ys = (ys.0.min(y), ys.1.max(y));
                any = true;
            }
        }
    }
    if !any {
        return None;
    }
    Some((xs.1 - xs.0, ys.1 - ys.0))
}

//! Sections and elevations: `section`, `elevation` (the four building elevations, `facing`, `at`).

use super::common::*;
use super::model as m;
use super::plans::shows;
use crate::commands::params::{opt_num, opt_point, opt_text, req_point};
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "section" => section(s, p),
        _ => elevation(s, p),
    }
}

// ---------------------------------------------------------------- names

pub const SECTION_WORD: [&str; 9] = ["Section", "Corte", "Sección", "Sektion", "Řez", "Coupe", "Doorsnede", "Schnitt", "Sezione"];
pub const ELEVATION_WORD: [&str; 9] = ["Elevation", "Elevação", "Elevación", "Fasad", "Pohled", "Élévation", "Gevel", "Ansicht", "Prospetto"];
const NORTH: [&str; 9] = ["North", "Norte", "Norte", "Norr", "Sever", "Nord", "Noord", "Norden", "Nord"];
const SOUTH: [&str; 9] = ["South", "Sul", "Sur", "Söder", "Jih", "Sud", "Zuid", "Süden", "Sud"];
const EAST: [&str; 9] = ["East", "Leste", "Este", "Öster", "Východ", "Est", "Oost", "Osten", "Est"];
const WEST: [&str; 9] = ["West", "Oeste", "Oeste", "Väster", "Západ", "Ouest", "West", "Westen", "Ovest"];

/// The categories whose names are views' names, which no two may share.
pub const NAMED_VIEWS: &[&str] = &["planview", "section", "elevation", "view3d", "schedule"];

/// Every name a view (or a level) goes by.
pub fn taken_names(pr: &Project) -> Vec<String> {
    pr.elements
        .values()
        .filter(|e| NAMED_VIEWS.contains(&cat(e)) || cat(e) == "level")
        .filter_map(|e| s_of(e, "name").map(|s| s.to_string()))
        .collect()
}

/// `<word> n`, the first n no view has.
pub fn numbered_name(pr: &Project, word: &str) -> String {
    let taken = taken_names(pr);
    let mut n = 1u64;
    loop {
        let c = format!("{} {}", word, n);
        if !taken.contains(&c) {
            return c;
        }
        n += 1;
    }
}

/// The word itself where no view has it, else `<word> 2`, `<word> 3`…
pub fn word_name(pr: &Project, word: &str) -> String {
    let taken = taken_names(pr);
    if !taken.iter().any(|t| t == word) {
        return word.to_string();
    }
    let mut n = 2u64;
    loop {
        let c = format!("{} {}", word, n);
        if !taken.contains(&c) {
            return c;
        }
        n += 1;
    }
}

// ---------------------------------------------------------------- section

fn section(s: &mut Session, p: &Value) -> R<Value> {
    let start = req_point(p, "section", "start")?;
    let end = req_point(p, "section", "end")?;
    let depth = opt_num(p, "section", "depth")?;
    let name = opt_text(p, "section", "name")?;
    let pr = &mut s.project;
    let name = match name {
        Some(n) => n,
        None => numbered_name(pr, word(pr, SECTION_WORD)),
    };
    let id = make_view(pr, "section", &name, start, end, depth);
    Ok(jobj! {"id" => id, "name" => name})
}

fn make_view(pr: &mut Project, cat: &str, name: &str, start: [f64; 2], end: [f64; 2], depth: Option<f64>) -> u64 {
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => cat,
            "name" => name,
            "start" => start,
            "end" => end,
            "depth" => match depth { Some(d) => Value::f(d), None => Value::Null },
        },
    );
    id
}

// ---------------------------------------------------------------- elevation

#[derive(Clone, Copy, PartialEq, Debug)]
enum Side {
    North,
    South,
    East,
    West,
}

impl Side {
    fn word(self, pr: &Project) -> &'static str {
        word(
            pr,
            match self {
                Side::North => NORTH,
                Side::South => SOUTH,
                Side::East => EAST,
                Side::West => WEST,
            },
        )
    }
}

/// An elevation's line round the box: 3 m out from the side it shows (or through `at`), a metre
/// past the box at each end, looking at the building.
fn side_line(side: Side, (lo, hi): shows::BBox, at: Option<[f64; 2]>) -> ([f64; 2], [f64; 2]) {
    const OUT: f64 = 3000.0;
    const PAST: f64 = 1000.0;
    match side {
        Side::North => {
            let y = at.map_or(hi[1] + OUT, |a| a[1]);
            ([hi[0] + PAST, y], [lo[0] - PAST, y])
        }
        Side::South => {
            let y = at.map_or(lo[1] - OUT, |a| a[1]);
            ([lo[0] - PAST, y], [hi[0] + PAST, y])
        }
        Side::East => {
            let x = at.map_or(hi[0] + OUT, |a| a[0]);
            ([x, lo[1] - PAST], [x, hi[1] + PAST])
        }
        Side::West => {
            let x = at.map_or(lo[0] - OUT, |a| a[0]);
            ([x, hi[1] + PAST], [x, lo[1] - PAST])
        }
    }
}

/// The side of the box a point is on, as seen from its middle.
fn side_of((lo, hi): shows::BBox, at: [f64; 2]) -> Side {
    let c = [(lo[0] + hi[0]) / 2.0, (lo[1] + hi[1]) / 2.0];
    let dx = at[0] - c[0];
    let dy = at[1] - c[1];
    if dx.abs() > dy.abs() {
        if dx > 0.0 {
            Side::East
        } else {
            Side::West
        }
    } else if dy > 0.0 {
        Side::North
    } else {
        Side::South
    }
}

fn elevation(s: &mut Session, p: &Value) -> R<Value> {
    const CMD: &str = "elevation";
    let depth = opt_num(p, CMD, "depth")?;
    let name = opt_text(p, CMD, "name")?;
    let at = opt_point(p, CMD, "at")?;
    let facing = match opt_text(p, CMD, "facing")? {
        None => None,
        Some(f) => Some(match f.to_lowercase().as_str() {
            "north" => Side::North,
            "south" => Side::South,
            "east" => Side::East,
            "west" => Side::West,
            _ => return Err(format!("{}: `facing` is north, south, east or west, not `{}`", CMD, f)),
        }),
    };
    let start = opt_point(p, CMD, "start")?;
    let end = opt_point(p, CMD, "end")?;
    let pr = &mut s.project;
    match (start, end) {
        (Some(a), Some(b)) => {
            let name = match name {
                Some(n) => n,
                None => numbered_name(pr, word(pr, ELEVATION_WORD)),
            };
            let id = make_view(pr, "elevation", &name, a, b, depth);
            return Ok(jobj! {"id" => id, "name" => name});
        }
        (None, None) => {}
        _ => return Err(format!("{}: give both `start` and `end`, or neither", CMD)),
    }
    let Some(bx) = shows::walls_and_floors_box(pr) else {
        return Err(format!(
            "{}: there are no walls or floors to look at; draw some, or give `start` and `end`",
            CMD
        ));
    };
    let one = match (facing, at) {
        (Some(f), _) => Some(f),
        (None, Some(a)) => Some(side_of(bx, a)),
        (None, None) => None,
    };
    if let Some(side) = one {
        let (a, b) = side_line(side, bx, at);
        let name = match name {
            Some(n) => n,
            None => word_name(pr, side.word(pr)),
        };
        let id = make_view(pr, "elevation", &name, a, b, depth);
        return Ok(jobj! {"id" => id, "name" => name});
    }
    // the four building elevations not there yet
    let mut ids = Vec::new();
    for side in [Side::North, Side::South, Side::East, Side::West] {
        let w = side.word(pr);
        let there = pr.elements.values().any(|e| cat(e) == "elevation" && s_of(e, "name") == Some(w));
        if there {
            continue;
        }
        let (a, b) = side_line(side, bx, None);
        let nm = match &name {
            Some(n) => n.clone(),
            None => word_name(pr, w),
        };
        ids.push(Value::u(make_view(pr, "elevation", &nm, a, b, depth)));
    }
    if ids.is_empty() {
        return Err(format!("{}: the four building elevations are there already", CMD));
    }
    Ok(jobj! {"ids" => Value::Arr(ids)})
}

// ---------------------------------------------------------------- the model's rules

/// The model rules of this part, checked after every command: those of every view and sheet
/// this area keeps are checked in one pass, element by element, in `views_check`.
pub fn check(pr: &Project) -> R<()> {
    super::plans::views_check(pr)
}

/// A section's or an elevation's own rules: a name, a length, a depth, a crop that runs up.
pub fn check_line_view(pr: &Project, id: u64, e: &Value) -> R<()> {
    let c = cat(e);
    let name = s_of(e, "name").unwrap_or("");
    if name.trim().is_empty() {
        return Err(format!("{} {}: a view needs a name", c, id));
    }
    let (_, _, len, _) = shows::view_line(e);
    if !(len > 1.0) {
        return Err(format!("{} {}: too short ({} mm)", c, id, disp(len)));
    }
    if let Some(d) = f_of(e, "depth") {
        if !(d > 0.0) {
            return Err(format!("{} {} depth must be above zero, got {}", c, id, disp(d)));
        }
    }
    if let Some(a) = e.get("crop").and_then(|x| x.as_arr()) {
        if a.len() == 2 {
            let b = a[0].as_f64().unwrap_or(0.0);
            let t = a[1].as_f64().unwrap_or(0.0);
            if !(t - b > 1.0) {
                return Err(format!(
                    "{} {}: its crop runs from a bottom up to a top above it, not from {} to {}",
                    c,
                    id,
                    disp(b),
                    disp(t)
                ));
            }
        }
    }
    let _ = pr;
    Ok(())
}

/// What `elements` shows of this part's elements beyond their own fields: how long the line is,
/// and the way it looks.
pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
    let Some(e) = pr.el(id) else { return };
    let s = pt_of(e, "start").unwrap_or([0.0, 0.0]);
    let t = pt_of(e, "end").unwrap_or([0.0, 0.0]);
    let dx = t[0] - s[0];
    let dy = t[1] - s[1];
    let len = (dx * dx + dy * dy).sqrt();
    x.set("length", Value::f(len));
    let look = if len > 0.0 { [-dy / len, dx / len] } else { [0.0, 0.0] };
    x.set("looking", Value::from([zero(look[0]), zero(look[1])]));
}

/// -0 as 0, as the original shows a direction.
fn zero(v: f64) -> f64 {
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

#[allow(dead_code)]
fn _unused(pr: &Project) {
    let _ = m::dist([0.0, 0.0], [0.0, 0.0]);
    let _ = pr;
}

//! Plans: `crop`, `duplicate_view` (plan views: duplicate, detailing, dependent); the rules of
//! every view and sheet; what goes with a view, a sheet or a level when it is deleted.

pub mod shows;

use super::common::*;
use super::model as m;
use crate::commands::params::{get, given, opt_text};
use crate::json::{Map, Value};
use crate::project::Project;
use crate::session::Session;
use std::collections::BTreeSet;

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "crop" => crop(s, p),
        _ => duplicate_view(s, p),
    }
}

// ---------------------------------------------------------------- finding views

/// A view by id, GUID or name, as `crop` and `duplicate_view` take one; `sheets` lets a sheet's
/// number name it. "`view`: X is not a view", "no view named `X`".
pub fn find_any_view(pr: &Project, cmd: &str, v: &Value, sheets: bool) -> R<u64> {
    let not = || format!("{}: `view`: {} is not a view", cmd, v.to_compact());
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(not)?;
            if pr.elements.contains_key(&id) {
                Ok(id)
            } else {
                Err(not())
            }
        }
        Value::Str(s) => {
            for (id, e) in &pr.elements {
                let c = cat(e);
                let named = if c == "sheet" {
                    sheets && s_of(e, "number") == Some(s.as_str())
                } else {
                    is_view_category(c) && s_of(e, "name") == Some(s.as_str())
                };
                if named {
                    return Ok(*id);
                }
            }
            if let Ok(id) = s.trim().parse::<u64>() {
                if pr.elements.contains_key(&id) {
                    return Ok(id);
                }
            }
            if let Some(g) = crate::model::normalize_guid(s) {
                if let Some(id) = pr.find_guid(&g) {
                    return Ok(id);
                }
            }
            Err(format!("{}: no view named `{}`", cmd, s))
        }
        _ => Err(not()),
    }
}

/// How a view is named in messages: its name, a sheet as "sheet A101".
fn what_view(pr: &Project, id: u64) -> String {
    match pr.el(id) {
        Some(e) if cat(e) == "sheet" => format!("sheet {}", s_of(e, "number").unwrap_or("")),
        Some(e) => match s_of(e, "name") {
            Some(n) => n.to_string(),
            None => cat_id(pr, id),
        },
        None => String::new(),
    }
}

// ---------------------------------------------------------------- crop

fn crop(s: &mut Session, p: &Value) -> R<Value> {
    const CMD: &str = "crop";
    let pr = &mut s.project;
    let view = match get(p, "view") {
        Some(v) => find_any_view(pr, CMD, v, true)?,
        None => default_plan(pr).ok_or_else(|| format!("{}: the project has no level", CMD))?,
    };
    // the region: two corners, or null to uncrop; none, what the view shows
    let region: Option<Option<[[f64; 2]; 2]>> = if !given(p, "region") {
        None
    } else {
        match p.get("region").unwrap() {
            Value::Null => Some(None),
            Value::Arr(a) => {
                let mut pts = Vec::new();
                for q in a {
                    match crate::commands::params::point_of(q) {
                        Some(x) => pts.push(x),
                        None => {
                            return Err(format!("{}: `region`: {} is not a point [x, y] in mm", CMD, q.to_compact()))
                        }
                    }
                }
                if pts.len() != 2 {
                    return Err(format!("{}: `region` is two corners, [[x, y], [x, y]]", CMD));
                }
                Some(Some([pts[0], pts[1]]))
            }
            _ => return Err(format!("{}: `region` [[x, y], …] is required", CMD)),
        }
    };
    let c = cat_of(pr, view);
    match c.as_str() {
        "level" | "planview" => {
            let e = pr.el_mut(view).unwrap();
            match region {
                Some(None) => {
                    e.remove("crop");
                    Ok(jobj! {"crop" => Value::Null, "view" => view})
                }
                Some(Some([a, b])) => {
                    let v = Value::Arr(vec![Value::from(a), Value::from(b)]);
                    set_crop(e, v.clone());
                    Ok(jobj! {"crop" => v, "view" => view})
                }
                None => {
                    let Some((lo, hi)) = shows::plan_shows(pr, view) else {
                        return Err(format!("{}: {} shows nothing to crop to", CMD, what_view(pr, view)));
                    };
                    let v = Value::Arr(vec![
                        Value::from(r3p([lo[0] - 1000.0, lo[1] - 1000.0])),
                        Value::from(r3p([hi[0] + 1000.0, hi[1] + 1000.0])),
                    ]);
                    let e = pr.el_mut(view).unwrap();
                    set_crop(e, v.clone());
                    Ok(jobj! {"crop" => v, "view" => view})
                }
            }
        }
        "section" | "elevation" => match region {
            Some(None) => {
                pr.el_mut(view).unwrap().remove("crop");
                Ok(jobj! {"crop" => Value::Null, "view" => view})
            }
            Some(Some([a, b])) => {
                if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                    return Err(format!(
                        "{}: a crop region runs from its bottom left corner to its top right one (in a plan, south-west to north-east)",
                        CMD
                    ));
                }
                let e = pr.el(view).unwrap().clone();
                let (st, d, _, _) = shows::view_line(&e);
                let ns = [st[0] + d[0] * a[0], st[1] + d[1] * a[0]];
                let ne = [st[0] + d[0] * b[0], st[1] + d[1] * b[0]];
                let v = Value::Arr(vec![Value::f(a[1]), Value::f(b[1])]);
                {
                    let x = pr.el_mut(view).unwrap();
                    x.set("start", Value::from(ns));
                    x.set("end", Value::from(ne));
                    set_crop(x, v.clone());
                }
                // the notes in it stay where they are: along the line from its new start
                keep_annotation(pr, view, a[0]);
                Ok(jobj! {"crop" => v, "view" => view})
            }
            None => {
                let (_, _, v0, v1) = shows::section_frame(pr, view);
                let v = Value::Arr(vec![Value::f(r3(v0)), Value::f(r3(v1))]);
                set_crop(pr.el_mut(view).unwrap(), v.clone());
                Ok(jobj! {"crop" => v, "view" => view})
            }
        },
        _ => Err(format!(
            "{}: {} isn't a plan, a section or an elevation; only those crop",
            CMD,
            what_view(pr, view)
        )),
    }
}

/// Sets an element's crop where its fields put it (after its view range or its depth).
fn set_crop(e: &mut Value, v: Value) {
    if e.get("crop").is_some() {
        e.set("crop", v);
        return;
    }
    let order: &[&str] = match cat(e) {
        "level" => &["guid", "category", "name", "elevation", "view_range", "crop", "extent", "graphics", "section_box", "computation_height"],
        "planview" => &["guid", "category", "level", "name", "view_range", "crop", "graphics", "parent", "section_box"],
        _ => &["guid", "category", "name", "start", "end", "depth", "crop", "graphics"],
    };
    insert_in_order(e, "crop", v, order);
}

/// Puts a key into an object at its place in a struct's field order.
pub fn insert_in_order(e: &mut Value, key: &str, v: Value, order: &[&str]) {
    let Some(map) = e.as_obj_mut() else { return };
    if map.contains(key) {
        map.insert(key, v);
        return;
    }
    let rank = |k: &str| order.iter().position(|o| *o == k);
    let mine = rank(key).unwrap_or(usize::MAX);
    let pos = map
        .items
        .iter()
        .position(|(k, _)| match rank(k) {
            Some(r) => r > mine,
            None => false,
        })
        .unwrap_or(map.items.len());
    map.items.insert(pos, (key.to_string(), v));
}

/// A section's notes and lines stay put as its start moves `by` along its line: their places
/// along it, measured from its start, move back by as much.
fn keep_annotation(pr: &mut Project, view: u64, by: f64) {
    if by == 0.0 {
        return;
    }
    let g = guid(pr, view);
    let ids: Vec<u64> = pr
        .elements
        .iter()
        .filter(|(_, e)| s_of(e, "view") == Some(g.as_str()))
        .map(|(id, _)| *id)
        .collect();
    for id in ids {
        let e = pr.el_mut(id).unwrap();
        shift_points(e, [-by, 0.0]);
    }
}

fn shift_pt(v: &mut Value, d: [f64; 2]) {
    if let Some(a) = v.as_arr_mut() {
        if a.len() >= 2 {
            if let (Some(x), Some(y)) = (a[0].as_f64(), a[1].as_f64()) {
                a[0] = Value::f(x + d[0]);
                a[1] = Value::f(y + d[1]);
            }
        }
    }
}

/// Moves the points an element of annotation holds (in its view's own terms).
fn shift_points(e: &mut Value, d: [f64; 2]) {
    for k in ["at", "leader", "start", "end", "through", "centre"] {
        if let Some(v) = e.get_mut(k) {
            shift_pt(v, d);
        }
    }
    for k in ["points", "control", "fit"] {
        if let Some(Value::Arr(a)) = e.get_mut(k) {
            for q in a.iter_mut() {
                shift_pt(q, d);
            }
        }
    }
    if let Some(Value::Arr(a)) = e.get_mut("sketch") {
        for l in a.iter_mut() {
            for k in ["start", "end", "through"] {
                if let Some(v) = l.get_mut(k) {
                    shift_pt(v, d);
                }
            }
        }
    }
}

// ---------------------------------------------------------------- duplicate_view

const COPY_WORD: [&str; 9] = ["Copy", "Cópia", "Copia", "Kopiera", "Kopie", "Copie", "Kopie", "Kopie", "Copia"];
const DEPENDENT_WORD: [&str; 9] = [
    "Dependent",
    "Dependente",
    "Dependiente",
    "Beroende",
    "Závislý",
    "Dépendant",
    "Afhankelijk",
    "Abhängig",
    "Dipendente",
];

/// The categories of annotation a view holds by its `view`.
pub const ANNOTATION: &[&str] = &[
    "text",
    "dimension",
    "tag",
    "spot",
    "spotslope",
    "spot_slope",
    "line",
    "region",
    "detailgroup",
    "repeatingdetail",
    "dimension3d",
];

/// Each annotation category's fields in order, where `view` goes in a copy that has none.
fn annotation_order(c: &str) -> &'static [&'static str] {
    match c {
        "tag" => &["guid", "category", "host", "view", "offset", "leader", "label"],
        "dimension" => &[
            "guid", "category", "level", "view", "kind", "orient", "refs", "at", "type", "prefix", "suffix", "above", "below",
            "replace", "equality", "texts", "equal", "locked", "alignment",
        ],
        _ => &["guid", "category", "view"],
    }
}

fn duplicate_view(s: &mut Session, p: &Value) -> R<Value> {
    const CMD: &str = "duplicate_view";
    let pr = &mut s.project;
    let view = match get(p, "view") {
        Some(v) => find_any_view(pr, CMD, v, false)?,
        None => default_plan(pr).ok_or_else(|| format!("{}: the project has no level", CMD))?,
    };
    let mode = match opt_text(p, CMD, "mode")? {
        None => "duplicate".to_string(),
        Some(m) => match m.as_str() {
            "duplicate" | "detailing" | "dependent" => m,
            _ => return Err(format!("{}: `mode` is duplicate, detailing or dependent, not `{}`", CMD, m)),
        },
    };
    let name = opt_text(p, CMD, "name")?;
    let c = cat_of(pr, view);
    if c != "level" && c != "planview" {
        return Err(format!(
            "{}: {} isn't a plan: plans are duplicated, sections, elevations, schedules, sheets and the 3D view not yet",
            CMD,
            what_view(pr, view)
        ));
    }
    let src = pr.el(view).unwrap().clone();
    if mode == "dependent" && src.get("parent").is_some() {
        return Err(format!(
            "{}: {} is a dependent view, which has none of its own: make it of its parent",
            CMD,
            what_view(pr, view)
        ));
    }
    let level = plan_level(pr, view).ok_or_else(|| format!("{}: {} has no level", CMD, what_view(pr, view)))?;
    let src_name = s_of(&src, "name").unwrap_or("").to_string();
    let name = match name {
        Some(n) => n,
        None => {
            let w = if mode == "dependent" { word(pr, DEPENDENT_WORD) } else { word(pr, COPY_WORD) };
            super::sections::numbered_name(pr, &format!("{} {}", src_name, w))
        }
    };
    let mut e = Map::new();
    e.insert("guid", Value::s(&crate::rand::guid()));
    e.insert("category", Value::s("planview"));
    e.insert("level", Value::s(&guid(pr, level)));
    e.insert("name", Value::s(&name));
    let vr = src.get("view_range").cloned().unwrap_or_else(|| {
        jobj! {"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0}
    });
    e.insert("view_range", vr);
    if let Some(c) = src.get("crop") {
        e.insert("crop", c.clone());
    }
    if mode == "dependent" {
        e.insert("parent", Value::s(&guid(pr, view)));
    } else {
        if let Some(g) = src.get("graphics") {
            e.insert("graphics", g.clone());
        }
        if let Some(b) = src.get("section_box") {
            e.insert("section_box", b.clone());
        }
    }
    let id = pr.alloc_id();
    let new_guid = s_of(&Value::Obj(e.clone()), "guid").unwrap().to_string();
    pr.elements.insert(id, Value::Obj(e));
    let mut copies = 0u64;
    if mode == "detailing" {
        let src_ids: Vec<u64> = pr
            .elements
            .iter()
            .filter(|(i, x)| **i != id && ANNOTATION.contains(&cat(x)) && in_view_own(pr, view, x))
            .map(|(i, _)| *i)
            .collect();
        for sid in src_ids {
            let mut x = pr.el(sid).unwrap().clone();
            x.set("guid", Value::s(&crate::rand::guid()));
            let ord = annotation_order(cat(&x));
            insert_in_order(&mut x, "view", Value::s(&new_guid), ord);
            renumber_parts(pr, &mut x);
            let nid = pr.alloc_id();
            pr.elements.insert(nid, x);
            copies += 1;
        }
    }
    Ok(jobj! {"annotations" => copies, "id" => id, "level" => level, "name" => name})
}

/// Whether annotation is a view's own (not a dependent's parent's): by its `view`, or with none
/// a dimension or a tag on a level's own plan.
fn in_view_own(pr: &Project, view: u64, e: &Value) -> bool {
    let g = guid(pr, view);
    if let Some(v) = s_of(e, "view") {
        return v == g;
    }
    if cat_of(pr, view) != "level" {
        return false;
    }
    match cat(e) {
        "dimension" => s_of(e, "level") == Some(g.as_str()),
        "tag" => shows::host_level(pr, e).as_deref() == Some(g.as_str()),
        _ => false,
    }
}

/// A copy's parts (a region's sketch lines…) get ids and GUIDs of their own.
fn renumber_parts(pr: &mut Project, x: &mut Value) {
    if let Some(Value::Arr(a)) = x.get_mut("sketch") {
        let n = a.len();
        let mut ids = Vec::new();
        for _ in 0..n {
            ids.push(pr.alloc_lib_id());
        }
        for (l, nid) in a.iter_mut().zip(ids) {
            if l.get("id").is_some() {
                l.set("id", Value::u(nid));
            }
            if l.get("guid").is_some() {
                l.set("guid", Value::s(&crate::rand::guid()));
            }
        }
    }
}

// ---------------------------------------------------------------- the rules of views and sheets

/// The rules of every view and sheet this area keeps, element by element in id order: a
/// section's or an elevation's line, depth and crop; a plan's crop; a plan view's level; names no
/// two views share and no view shares with a level; sheets' numbers and sizes; a viewport's
/// scale, and a view on one sheet.
pub fn views_check(pr: &Project) -> R<()> {
    let level_names: Vec<String> = pr
        .elements
        .values()
        .filter(|e| cat(e) == "level")
        .filter_map(|e| s_of(e, "name").map(|s| s.to_string()))
        .collect();
    let mut view_names: Vec<String> = Vec::new();
    let mut numbers: Vec<String> = Vec::new();
    let mut placed: Vec<(String, u64)> = Vec::new();
    let mut level_clash: Option<String> = None;
    for (id, e) in &pr.elements {
        let id = *id;
        let c = cat(e);
        match c {
            "section" | "elevation" | "view3d" | "schedule" | "planview" => {
                if c == "section" || c == "elevation" {
                    super::sections::check_line_view(pr, id, e)?;
                }
                let name = s_of(e, "name").unwrap_or("").to_string();
                if c == "planview" {
                    if name.trim().is_empty() {
                        return Err(format!("planview {}: a view needs a name", id));
                    }
                    if level_names.contains(&name) {
                        return Err(format!(
                            "planview {}: a level is already named `{}`; a plan view of it needs another name",
                            id, name
                        ));
                    }
                    if ref_id(pr, e, "level").map(|l| cat_of(pr, l)) != Some("level".to_string()) {
                        return Err(format!(
                            "planview {}: level {} doesn't exist",
                            id,
                            s_of(e, "level").unwrap_or("")
                        ));
                    }
                    check_plan_crop(id, e)?;
                } else if level_names.contains(&name) && level_clash.is_none() {
                    level_clash = Some(name.clone());
                }
                if view_names.contains(&name) {
                    return Err(format!("{} {}: another view is already named `{}`", c, id, name));
                }
                view_names.push(name);
            }
            "level" => check_plan_crop(id, e)?,
            "sheet" => {
                let num = s_of(e, "number").unwrap_or("").to_string();
                if num.trim().is_empty() {
                    return Err(format!("sheet {}: a sheet needs a number", id));
                }
                if numbers.contains(&num) {
                    return Err(format!("sheet {}: another sheet is already numbered `{}`", id, num));
                }
                numbers.push(num);
                let size = s_of(e, "size").unwrap_or("");
                if super::sheets::paper::paper_size(size).is_none() {
                    return Err(format!(
                        "sheet {}: size `{}` isn't A0, A1, A2, A3 or A4, or an Arch / ANSI size",
                        id, size
                    ));
                }
            }
            "viewport" => {
                let sc = f_of(e, "scale").unwrap_or(100.0);
                if !(sc >= 1.0 && sc <= 100000.0) {
                    return Err(format!("viewport {}: scale 1 : {} isn't between 1 : 1 and 1 : 100000", id, disp(sc)));
                }
                let v = s_of(e, "view").unwrap_or("").to_string();
                if let Some((_, sheet)) = placed.iter().find(|(g, _)| *g == v) {
                    let vid = pr.find_guid(&v);
                    let vname = vid.map(|x| super::common::view_name(pr, x)).unwrap_or_default();
                    let sname = super::common::view_name(pr, *sheet);
                    return Err(format!(
                        "viewport {}: {} is on sheet {} already; a view goes on one sheet",
                        id, vname, sname
                    ));
                }
                if let Some(sh) = ref_id(pr, e, "sheet") {
                    placed.push((v, sh));
                }
            }
            _ => {}
        }
    }
    if let Some(n) = level_clash {
        return Err(format!("a view is named `{}`, as a level is; name it otherwise", n));
    }
    Ok(())
}

/// A plan's crop runs from its south-west corner to its north-east one.
fn check_plan_crop(id: u64, e: &Value) -> R<()> {
    if let Some((a, b)) = shows::plan_crop(e) {
        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
            return Err(format!(
                "{} {}: a crop region runs from its south-west corner to its north-east one (in a section, bottom left to top right)",
                cat(e),
                id
            ));
        }
    }
    Ok(())
}

/// The model rules of this part, checked after every command (in `views_check`, run once by
/// `sections::check`).
pub fn check(pr: &Project) -> R<()> {
    let _ = pr;
    Ok(())
}

/// What `elements` shows of this part's elements beyond their own fields: a plan view, nothing.
pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
    let _ = (pr, id, x);
}

// ---------------------------------------------------------------- delete

/// What else goes when these elements are deleted, as the original's `delete` takes it: the
/// annotation in a deleted view (notes, detail lines, dimensions, tags, spots, regions, groups,
/// repeating details), a deleted plan's dependent plan views, a level's plan views, the
/// viewports of a deleted view or sheet, and so on through what those take with them. The ids
/// that go besides `gone`, in id order.
pub fn dependents(pr: &Project, gone: &BTreeSet<u64>) -> Vec<u64> {
    let mut all: BTreeSet<u64> = gone.clone();
    loop {
        let guids: BTreeSet<String> = all.iter().filter_map(|id| pr.guid_of(*id)).collect();
        let mut more = Vec::new();
        for (id, e) in &pr.elements {
            if all.contains(id) {
                continue;
            }
            let refs = |k: &str| s_of(e, k).map_or(false, |g| guids.contains(g));
            let goes = match cat(e) {
                "viewport" => refs("sheet") || refs("view"),
                "planview" => refs("level") || refs("parent"),
                c if ANNOTATION.contains(&c) => refs("view"),
                _ => false,
            };
            if goes {
                more.push(*id);
            }
        }
        if more.is_empty() {
            break;
        }
        all.extend(more);
    }
    all.into_iter().filter(|id| !gone.contains(id)).collect()
}

