/// What a schedule's name in any language is of (in any case, trimmed).
pub fn schedule_of(name: &str) -> Option<&'static str> {
    let t = name.trim().to_lowercase();
    SCHEDULES
        .iter()
        .find(|(_, names)| names.iter().any(|n| n.to_lowercase() == t))
        .map(|(of, _)| *of)
