/// A category's schedule name in the project's language.
pub fn schedule_name(pr: &Project, of: &str) -> String {
    SCHEDULES
        .iter()
        .find(|(o, _)| *o == of)
        .map(|(_, names)| word(pr, *names).to_string())
        .unwrap_or_default()
}

/// A category's own columns: (field, heading).
fn default_fields(of: &str) -> Vec<&'static str> {
    match of {
        "room" => vec!["Number", "Name", "Level", "Area", "Perimeter"],
        "door" => vec!["Mark", "Type", "Width", "Height", "Level", "Wall"],
        "window" => vec!["Mark", "Type", "Width", "Height", "Sill", "Level", "Wall"],
        "wall" => vec!["Id", "Type", "Level", "Length", "Height", "Thickness"],
        "floor" => vec!["Id", "Type", "Level", "Area", "Thickness"],
        "level" => vec!["Elevation", "Name"],
        _ => vec![],
    }
}

/// A column's heading: its own, or its field's name (an area's with its unit).
fn heading_of(field: &str, heading: Option<&str>) -> String {
    let base = heading.unwrap_or(field).to_string();
    if field == "Area" {
        format!("{} (m²)", base)
    } else {
        base
    }
}

/// The elements a schedule lists, by id.
fn schedule_rows(pr: &Project, of: &str) -> Vec<u64> {
    let mut ids: Vec<u64> = pr.ids_of(of);
    if of == "level" {
        ids = crate::model::levels(pr);
    }
    ids
}

/// A cell's text, where it can be told: the element's own field as a schedule shows it.
fn cell_text(pr: &Project, id: u64, field: &str) -> String {
    let Some(e) = pr.el(id) else { return String::new() };
    let num = |x: f64| if x == x.trunc() && x.abs() < 1e15 { format!("{}", x as i64) } else { format!("{}", x) };
    match field {
        "Name" => s_of(e, "name").unwrap_or("").to_string(),
        "Number" => s_of(e, "number").unwrap_or("").to_string(),
        "Mark" => s_of(e, "mark").unwrap_or("").to_string(),
        "Elevation" => num(f_of(e, "elevation").unwrap_or(0.0)),
        "Id" => id.to_string(),
        "Level" => ref_id(pr, e, "level")
            .map(|l| name_of(pr, l))
            .or_else(|| ref_id(pr, e, "host").and_then(|h| pr.el(h)).and_then(|h| ref_id(pr, h, "level")).map(|l| name_of(pr, l)))
            .unwrap_or_default(),
        "Type" => lib_ref_name(pr, e, "type").unwrap_or_default(),
        "Wall" => ref_id(pr, e, "host").map(|h| h.to_string()).unwrap_or_default(),
        "Thickness" => num(super::super::model::wall_thickness(pr, e)),
        _ => String::new(),
    }
}

/// How big a schedule's table is on paper, mm: its title, 3.5 mm capitals, over its headings and
/// rows, 2.5 mm capitals, each column as wide as its widest text and 2 mm either side.
pub fn schedule_size(pr: &Project, id: u64) -> [f64; 2] {
    let Some(e) = pr.el(id) else { return [0.0, 0.0] };
    let of = s_of(e, "of").unwrap_or("room").to_string();
    let title = s_of(e, "name").unwrap_or("");
    let fields: Vec<(String, Option<String>)> = match e.get("fields").and_then(|f| f.as_arr()) {
        Some(a) if !a.is_empty() => a
            .iter()
            .map(|f| match f {
                Value::Str(s) => (s.clone(), None),
                _ => (
                    s_of(f, "name").unwrap_or("").to_string(),
                    s_of(f, "heading").map(|h| h.to_string()),
                ),
            })
            .collect(),
        _ => default_fields(&of).into_iter().map(|f| (f.to_string(), None)).collect(),
    };
    let rows = schedule_rows(pr, &of);
    const PAD: f64 = 2.0 * 2.0 * DENSITY;
    let mut table = 0.0;
    for (f, h) in &fields {
        let mut n = chars(&heading_of(f, h.as_deref()));
        for r in &rows {
            n = n.max(chars(&cell_text(pr, *r, f)));
        }
        table += text_px(n, 2.5) + PAD;
    }
    let title_w = text_px(chars(title), 3.5) + PAD;
    let w = ceil_px(if title_w > table { title_w } else { table });
    let h = 45.0 + 30.0 + 30.0 * rows.len() as f64;
    [w / DENSITY, h / DENSITY]
}

//! Sheets and what is placed on them: `sheet`, `place` (viewports; schedules and the 3D view come to be as first placed).

pub mod paper;

use super::common::*;
use crate::commands::params::{get, mm_of, opt_point, opt_text};
use crate::json::Value;
use crate::project::Project;
use crate::session::Session;

/// Runs the commands of this part.
pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
    match cid {
        "sheet" => sheet(s, p),
        _ => place(s, p),
    }
}

const UNNAMED: [&str; 9] = [
    "Unnamed",
    "Sem nome",
    "Sin nombre",
    "Namnlös",
    "Nepojmenovaný",
    "Sans nom",
    "Naamloos",
    "Unbenannt",
    "Senza nome",
];

// ---------------------------------------------------------------- sheet

fn sheet(s: &mut Session, p: &Value) -> R<Value> {
    let number = opt_text(p, "sheet", "number")?;
    let name = opt_text(p, "sheet", "name")?;
    let size = opt_text(p, "sheet", "size")?;
    let pr = &mut s.project;
    let number = match number {
        Some(n) => n,
        None => {
            let taken: Vec<String> = pr
                .elements
                .values()
                .filter(|e| cat(e) == "sheet")
                .filter_map(|e| s_of(e, "number").map(|x| x.to_string()))
                .collect();
            let mut n = 101u64;
            loop {
                let c = format!("A{}", n);
                if !taken.contains(&c) {
                    break c;
                }
                n += 1;
            }
        }
    };
    let name = name.unwrap_or_else(|| word(pr, UNNAMED).to_string());
    let size = match size {
        Some(x) => paper::normalize_size(&x),
        None => "A3".to_string(),
    };
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "sheet",
            "number" => number.clone(),
            "name" => name,
            "size" => size,
        },
    );
    Ok(jobj! {"id" => id, "number" => number})
}

// ---------------------------------------------------------------- place

/// A number in degrees, as `place` reads `azimuth` and `elevation`.
fn opt_degrees(p: &Value, key: &str) -> R<Option<f64>> {
    match get(p, key) {
        None => Ok(None),
        Some(v) => mm_of(v)
            .map(Some)
            .ok_or_else(|| format!("place: `{}` must be a number in mm, got {}", key, v.to_compact())),
    }
}

/// The sheet `place` puts the view on: by number, or by id.
fn find_sheet(pr: &Project, v: &Value) -> R<u64> {
    match v {
        Value::Str(s) => pr
            .elements
            .iter()
            .find(|(_, e)| cat(e) == "sheet" && s_of(e, "number") == Some(s.as_str()))
            .map(|(id, _)| *id)
            .ok_or_else(|| format!("place: no sheet numbered `{}`", s)),
        _ => {
            let not = || format!("place: `sheet`: {} is not a sheet", v.to_compact());
            let id = match v {
                Value::Num(_) => id_of(v).ok_or_else(not)?,
                _ => return Err(not()),
            };
            if cat_of(pr, id) == "sheet" {
                Ok(id)
            } else {
                Err(not())
            }
        }
    }
}

/// What `place` takes: a view by id, or by name (a level's, a section's, an elevation's, a
/// schedule's or a 3D view's; a schedule of a category by its name in any language, made as it
/// is first placed; the 3D view by `{3D}`, made likewise). Some(id) of a view there, or the
/// schedule or 3D view to make.
enum Placed {
    Here(u64),
    NewSchedule(&'static str),
    New3D,
}

const PLACEABLE: &[&str] = &["level", "planview", "section", "elevation", "schedule", "view3d"];

fn find_placed(pr: &Project, v: &Value) -> R<Placed> {
    let not = || format!("place: `view`: {} is not a plan, a section, an elevation, a schedule or a 3D view", v.to_compact());
    match v {
        Value::Num(_) => {
            let id = id_of(v).ok_or_else(not)?;
            if PLACEABLE.contains(&cat_of(pr, id).as_str()) {
                Ok(Placed::Here(id))
            } else {
                Err(not())
            }
        }
        Value::Str(s) => {
            for (id, e) in &pr.elements {
                if PLACEABLE.contains(&cat(e)) && s_of(e, "name") == Some(s.as_str()) {
                    return Ok(Placed::Here(*id));
                }
            }
            if let Some(of) = paper::schedule_of(s) {
                let name = paper::schedule_name(pr, of);
                if let Some((id, _)) = pr
                    .elements
                    .iter()
                    .find(|(_, e)| cat(e) == "schedule" && s_of(e, "name") == Some(name.as_str()))
                {
                    return Ok(Placed::Here(*id));
                }
                return Ok(Placed::NewSchedule(of));
            }
            if s == DEFAULT_3D {
                return Ok(Placed::New3D);
            }
            Err(format!("place: no level, section, elevation, schedule or 3D view named `{}`", s))
        }
        _ => Err(not()),
    }
}

/// The scale a view is drawn at: its template's where one controls it, its parent's for a
/// dependent plan, else its own, else 1 : 100.
pub fn scale_in_force(pr: &Project, view: u64) -> f64 {
    let Some(mut e) = pr.el(view) else { return 100.0 };
    if let Some(p) = ref_id(pr, e, "parent") {
        if let Some(pe) = pr.el(p) {
            e = pe;
        }
    }
    if let Some(t) = e.get("graphics").and_then(|g| s_of(g, "template")) {
        if let Some(name) = pr.lib_name(t) {
            if let Some(tp) = pr.section("view_templates").and_then(|v| v.get(&name)) {
                let controls = tp.get("controls").and_then(|c| c.as_arr());
                if controls.map_or(false, |c| c.iter().any(|x| x.as_str() == Some("scale"))) {
                    if let Some(sc) = tp.get("graphics").and_then(|g| f_of(g, "scale")) {
                        return sc;
                    }
                    if let Some(sc) = f_of(tp, "scale") {
                        return sc;
                    }
                }
            }
        }
    }
    e.get("graphics").and_then(|g| f_of(g, "scale")).unwrap_or(100.0)
}

fn place(s: &mut Session, p: &Value) -> R<Value> {
    let pr = &mut s.project;
    let sheet = match get(p, "sheet") {
        None => return Err("place: `sheet`, a sheet's number or id, is required".into()),
        Some(v) => find_sheet(pr, v)?,
    };
    let scale = match get(p, "scale") {
        None => None,
        Some(v) => Some(mm_of(v).ok_or_else(|| format!("place: `scale` must be a number in mm, got {}", v.to_compact()))?),
    };
    let at = opt_point(p, "place", "at")?;
    let placed = match get(p, "view") {
        None => {
            return Err("place: `view`, a level's, section's, elevation's, schedule's or 3D view's name or id, is required".into())
        }
        Some(v) => find_placed(pr, v)?,
    };
    let is_3d = match &placed {
        Placed::New3D => true,
        Placed::Here(id) => cat_of(pr, *id) == "view3d",
        _ => false,
    };
    let (azimuth, elevation) = if is_3d {
        (opt_degrees(p, "azimuth")?, opt_degrees(p, "elevation")?)
    } else {
        (None, None)
    };
    let view = match placed {
        Placed::Here(id) => id,
        Placed::NewSchedule(of) => {
            let id = pr.alloc_id();
            let name = paper::schedule_name(pr, of);
            pr.elements.insert(
                id,
                jobj! {"guid" => crate::rand::guid(), "category" => "schedule", "name" => name, "of" => of},
            );
            id
        }
        Placed::New3D => {
            let id = ensure_default_3d(pr);
            let e = pr.el_mut(id).unwrap();
            if let Some(a) = azimuth {
                e.set("azimuth", Value::f(a));
            }
            if let Some(el) = elevation {
                e.set("elevation", Value::f(el));
            }
            id
        }
    };
    let scale = match scale {
        Some(x) => x,
        None => match cat_of(pr, view).as_str() {
            "level" | "planview" | "section" | "elevation" => scale_in_force(pr, view),
            _ => 100.0,
        },
    };
    let size = paper::view_size(pr, view, scale);
    let at = match at {
        Some(a) => a,
        None => paper::default_place(pr, sheet, size),
    };
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "viewport",
            "sheet" => guid(pr, sheet),
            "view" => guid(pr, view),
            "at" => at,
            "scale" => scale,
        },
    );
    Ok(jobj! {"at" => at, "id" => id})
}

// ---------------------------------------------------------------- the model's rules

/// The model rules of this part, checked after every command (in `plans::views_check`).
pub fn check(pr: &Project) -> R<()> {
    let _ = pr;
    Ok(())
}

/// What `elements` shows of this part's elements beyond their own fields: a sheet's paper and
/// the viewports on it; a viewport's size on the paper and its title.
pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
    let Some(e) = pr.el(id) else { return };
    match cat(e) {
        "sheet" => {
            let (w, h) = paper::paper_size(s_of(e, "size").unwrap_or("A3")).unwrap_or((420.0, 297.0));
            x.set("paper", Value::from([w, h]));
            let g = guid(pr, id);
            let vps: Vec<Value> = pr
                .elements
                .iter()
                .filter(|(_, v)| cat(v) == "viewport" && s_of(v, "sheet") == Some(g.as_str()))
                .map(|(i, _)| Value::u(*i))
                .collect();
            x.set("viewports", Value::Arr(vps));
        }
        "viewport" => {
            let sz = paper::viewport_size(pr, id);
            x.set("size", Value::from(sz));
            let title = ref_id(pr, e, "view").map(|v| view_name(pr, v)).unwrap_or_default();
            x.set("title", Value::s(&title));
        }
        _ => {}
    }
}

//! Paper: the sheet sizes, the margins and title block a standard lays a sheet out with, where a
//! view goes on one by default, and how big each view is on paper (its viewport's size): a plan,
//! a section or an elevation drawn at its scale with its margins, the 3D view's picture, a
//! schedule's table lettered in our single-stroke capitals.

use super::super::common::*;
use super::super::plans::shows;
use crate::json::Value;
use crate::project::Project;

/// A sheet's drawing density: pixels to the paper millimetre.
pub const DENSITY: f64 = 5.0;

/// The sheet sizes, landscape: (name, width, height) in mm.
const SIZES: &[(&str, f64, f64)] = &[
    ("A0", 1189.0, 841.0),
    ("A1", 841.0, 594.0),
    ("A2", 594.0, 420.0),
    ("A3", 420.0, 297.0),
    ("A4", 297.0, 210.0),
    ("ARCH A", 304.8, 228.6),
    ("ARCH B", 457.2, 304.8),
    ("ARCH C", 609.6, 457.2),
    ("ARCH D", 914.4, 609.6),
    ("ARCH E", 1219.2, 914.4),
    ("ARCH E1", 1066.8, 762.0),
    ("ANSI A", 279.4, 215.9),
    ("ANSI B", 431.8, 279.4),
    ("ANSI C", 558.8, 431.8),
    ("ANSI D", 863.6, 558.8),
    ("ANSI E", 1117.6, 863.6),
    ("LETTER", 279.4, 215.9),
    ("TABLOID", 431.8, 279.4),
    ("LEDGER", 431.8, 279.4),
];

/// A size as a sheet keeps it: trimmed, in capitals.
pub fn normalize_size(s: &str) -> String {
    s.trim().to_uppercase()
}

/// The canonical name of a size as kept ("ARCHA" is ARCH A), if it is one.
fn canonical(size: &str) -> Option<&'static str> {
    if let Some(x) = SIZES.iter().find(|(n, _, _)| *n == size) {
        return Some(x.0);
    }
    for pre in ["ARCH", "ANSI"] {
        if let Some(rest) = size.strip_prefix(pre) {
            if rest.starts_with(' ') {
                continue;
            }
            let full = format!("{} {}", pre, rest);
            if let Some(x) = SIZES.iter().find(|(n, _, _)| *n == full) {
                return Some(x.0);
            }
        }
    }
    None
}

/// The paper a size names: width and height in mm, landscape.
pub fn paper_size(size: &str) -> Option<(f64, f64)> {
    let c = canonical(size)?;
    SIZES.iter().find(|(n, _, _)| *n == c).map(|x| (x.1, x.2))
}

/// The project's technical standard (iso unless it says).
pub fn standard(pr: &Project) -> String {
    pr.get("standard").and_then(|v| v.as_str()).unwrap_or("iso").to_string()
}

/// A standard's margins for a size: (left, the others) in mm.
fn margins(std: &str, size: &str) -> (f64, f64) {
    let c = canonical(size).unwrap_or("A3");
    match std {
        "nbr" => (25.0, if c == "A0" || c == "A1" { 10.0 } else { 7.0 }),
        "ansi" => (19.05, 12.7),
        "jis" => (20.0, if c == "A4" { 5.0 } else { 10.0 }),
        _ => (20.0, if c == "A4" { 7.0 } else { 10.0 }),
    }
}

/// The title block's height along the bottom of the frame.
const TITLE_BLOCK: f64 = 40.0;
/// How far inside the frame (and over the title block) views are laid out.
const INSET: f64 = 5.0;
/// The gap between a view and the next one placed right of it.
const GAP: f64 = 10.0;

/// Where views go on a sheet: (W, H, left, right, bottom, top) — the paper and its margins,
/// the bottom one over the title block.
fn layout(pr: &Project, sheet: &Value) -> (f64, f64, f64, f64, f64, f64) {
    let size = s_of(sheet, "size").unwrap_or("A3");
    let (w, h) = paper_size(size).unwrap_or((420.0, 297.0));
    let (l, o) = margins(&standard(pr), size);
    (w, h, l, o, o + TITLE_BLOCK, o)
}

/// The middle of the sheet's drawing area, where the first view goes.
pub fn middle(pr: &Project, sheet: &Value) -> [f64; 2] {
    let (w, h, l, r, b, t) = layout(pr, sheet);
    [(w + l - r) / 2.0, (h + b - t) / 2.0]
}

/// Where a view `size` wide and tall goes on a sheet by default: right of the views there, at
/// the middle's height, where it fits; else in the top right corner; on an empty sheet, in the
/// middle.
pub fn default_place(pr: &Project, sheet_id: u64, size: [f64; 2]) -> [f64; 2] {
    let sheet = pr.el(sheet_id).unwrap();
    let mid = middle(pr, sheet);
    let g = guid(pr, sheet_id);
    let mut right: Option<f64> = None;
    for (id, e) in &pr.elements {
        if cat(e) == "viewport" && s_of(e, "sheet") == Some(g.as_str()) {
            let at = pt_of(e, "at").unwrap_or([0.0, 0.0]);
            let sz = viewport_size(pr, *id);
            let r = at[0] + sz[0] / 2.0;
            right = Some(right.map_or(r, |x: f64| x.max(r)));
        }
    }
    let Some(right) = right else { return mid };
    let (w, h, _, r, _, t) = layout(pr, sheet);
    let x1 = w - (r + INSET);
    let y1 = h - (t + INSET);
    let x = right + GAP + size[0] / 2.0;
    if x + size[0] / 2.0 <= x1 + 1e-9 {
        [x, mid[1]]
    } else {
        [x1 - size[0] / 2.0, y1 - size[1] / 2.0]
    }
}

// ---------------------------------------------------------------- lettering

/// How wide a line of `n` letters of our single-stroke capitals is, `size` mm tall, in pixels:
/// each letter two thirds of its height wide, the next 11/12 of its height on.
pub fn text_px(n: usize, size: f64) -> f64 {
    if n == 0 {
        return 0.0;
    }
    let h = size * DENSITY;
    h * (11.0 * n as f64 / 12.0 - 0.25)
}

fn chars(s: &str) -> usize {
    s.chars().count()
}

/// Whole pixels up from a measure (what is within a millionth of a pixel counts as on it).
fn ceil_px(x: f64) -> f64 {
    (x - 1e-6).ceil()
}

// ---------------------------------------------------------------- sizes of views on paper

/// How big a viewport's view is on its sheet, mm.
pub fn viewport_size(pr: &Project, vp: u64) -> [f64; 2] {
    let Some(e) = pr.el(vp) else { return [0.0, 0.0] };
    let scale = f_of(e, "scale").unwrap_or(100.0);
    match ref_id(pr, e, "view") {
        Some(v) => view_size(pr, v, scale),
        None => [0.0, 0.0],
    }
}

/// How big a view is on paper at 1 : `scale`, mm: what it shows at the scale with 12 mm round
/// it (a section's and an elevation's levels' heads on their right), the 3D view's picture, a
/// schedule's table.
pub fn view_size(pr: &Project, view: u64, scale: f64) -> [f64; 2] {
    let Some(e) = pr.el(view) else { return [0.0, 0.0] };
    let k = DENSITY / scale;
    const MARGIN: f64 = 2.0 * 12.0 * DENSITY;
    match cat(e) {
        "level" | "planview" => {
            let (lo, hi) = shows::plan_crop(e)
                .or_else(|| shows::plan_shows(pr, view))
                .unwrap_or(([0.0, 0.0], [10000.0, 10000.0]));
            [ceil_px((hi[0] - lo[0]) * k + MARGIN) / DENSITY, ceil_px((hi[1] - lo[1]) * k + MARGIN) / DENSITY]
        }
        "section" | "elevation" => {
            let (u0, u1, v0, v1) = shows::section_frame(pr, view);
            let heads = level_heads_px(pr);
            [ceil_px((u1 - u0) * k + MARGIN + heads) / DENSITY, ceil_px((v1 - v0) * k + MARGIN) / DENSITY]
        }
        "view3d" => {
            let az = f_of(e, "azimuth").unwrap_or(-45.0);
            let el = f_of(e, "elevation").unwrap_or(30.0);
            match shows::view3d_extent(pr, Some(view), az, el) {
                None => [1.0 / DENSITY, 1.0 / DENSITY],
                Some((w, h)) => {
                    let cap = |x: f64| ceil_px(x * k + MARGIN).min(4096.0).max(1.0) / DENSITY;
                    [cap(w), cap(h)]
                }
            }
        }
        "schedule" => schedule_size(pr, view),
        _ => [0.0, 0.0],
    }
}

/// The room a section's level heads take right of its levels' lines: a gap, the widest name or
/// height lettered 2 mm tall, and a little more.
fn level_heads_px(pr: &Project) -> f64 {
    let mut n = 0usize;
    for id in crate::model::levels(pr) {
        let e = pr.el(id).unwrap();
        n = n.max(chars(s_of(e, "name").unwrap_or("")));
        n = n.max(chars(&height_text(f_of(e, "elevation").unwrap_or(0.0))));
    }
    12.0 + text_px(n, 2.0)
}

/// A level's height as its head letters it.
fn height_text(z: f64) -> String {
    if z == z.trunc() && z.abs() < 1e15 {
        format!("{}", z as i64)
    } else {
        format!("{}", z)
    }
}

