import math, itertools
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def add(a, b): return (a[0] + b[0], a[1] + b[1])
def mul(a, k): return (a[0] * k, a[1] * k)
def cross(a, b): return a[0] * b[1] - a[1] * b[0]
def dot(a, b): return a[0] * b[0] + a[1] * b[1]
def norm(a): return math.sqrt(a[0] * a[0] + a[1] * a[1])
def unit_div(a):
    l = norm(a); return (a[0] / l, a[1] / l)
def unit_inv(a):
    l = norm(a); r = 1.0 / l; return (a[0] * r, a[1] * r)
def isect(p, u, q, v):
    den = cross(u, v)
    t = cross(sub(q, p), v) / den
    return add(p, mul(u, t))
def isect2(p, u, q, v):
    # solve p + u t = q + v s by Cramer's rule on the 2x2 system
    den = u[0] * (-v[1]) - (-v[0]) * u[1]
    r = sub(q, p)
    t = (r[0] * (-v[1]) - (-v[0]) * r[1]) / den
    return add(p, mul(u, t))
