        let (idx, other) = if *at_start { (0, 1) } else { (1, 0) };
        w.left[idx] = capped(&w.centre, dl[other], at);
        w.right[idx] = capped(&w.centre, dr[other], at);
    }
    for (a, b) in pairs {
        let (i, si, _) = ends[a];
        let (j, sj, _) = ends[b];
        mitre(&mut ws, (i, si), (j, sj));
    }'''
