import math, itertools
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def add(a, b): return (a[0] + b[0], a[1] + b[1])
def mul(a, k): return (a[0] * k, a[1] * k)
def cross(a, b): return a[0] * b[1] - a[1] * b[0]
def dot(a, b): return a[0] * b[0] + a[1] * b[1]
def nrm(a): return math.sqrt(a[0] * a[0] + a[1] * a[1])
def udiv(a):
    l = nrm(a); return (a[0] / l, a[1] / l)
def uinv(a):
    l = nrm(a); r = 1 / l; return (a[0] * r, a[1] * r)
h = 100.0
# joint: A = (0,0)->(5000,3000), B = (5000,3000)->(9000,1000); target: the left (outer, upper) mitre point's y
A0, C, B1 = (0.0, 0.0), (5000.0, 3000.0), (9000.0, 1000.0)
target_y = 3113.99232570313
# second case: rot box corner 2 and 1 targets
res = []
for un, unit in [('div', udiv), ('inv', uinv)]:
    ua = unit(sub(C, A0)); ub = unit(sub(B1, C))
    na = (-ua[1], ua[0]); nb = (-ub[1], ub[0])
    da = sub(C, A0); db = sub(B1, C)
    pts = {
        'A.s': add(A0, mul(na, h)), 'A.e': add(C, mul(na, h)),
        'B.s': add(C, mul(nb, h)), 'B.e': add(B1, mul(nb, h)),
    }
    # face points with caps (free start of A: A.e - da ; free end of B: B.s + db)
    pts['A.s cap'] = sub(pts['A.e'], da)
    pts['B.e cap'] = add(pts['B.s'], db)
    dirs_a = {'ua': ua, 'da': da, '-ua': mul(ua, -1), '-da': mul(da, -1)}
    dirs_b = {'ub': ub, 'db': db, '-ub': mul(ub, -1), '-db': mul(db, -1)}
    for (pa_n, pa), (pb_n, pb) in itertools.product([(k, v) for k, v in pts.items() if k.startswith('A')], [(k, v) for k, v in pts.items() if k.startswith('B')]):
        for (dan, dav), (dbn, dbv) in itertools.product(dirs_a.items(), dirs_b.items()):
            den = cross(dav, dbv)
            if den == 0: continue
            t = cross(sub(pb, pa), dbv) / den
            P = add(pa, mul(dav, t))
            if P[1] == target_y:
                res.append(('A-based', un, pa_n, dan, pb_n, dbn))
            s_ = cross(sub(pa, pb), dav) / cross(dbv, dav)
            Q = add(pb, mul(dbv, s_))
            if Q[1] == target_y:
                res.append(('B-based', un, pb_n, dbn, pa_n, dan))
    # bisector forms
    bis = unit(add(na, nb))
    for k in [h / dot(bis, na), h / dot(bis, nb)]:
        P = add(C, mul(bis, k))
        if P[1] == target_y: res.append(('bisector', un))
    s = add(na, nb)
    P = add(C, mul(s, h / (1 + dot(na, nb))))
    if P[1] == target_y: res.append(('nsum', un))
for r in res[:30]: print(r)
print(len(res))

