1	//! Sheets and what is placed on them: `sheet`, `place` (viewports; schedules and the 3D view come to be as first placed).
2	
3	pub mod paper;
4	
5	use super::common::*;
6	use crate::commands::params::{get, mm_of, opt_point, opt_text};
7	use crate::json::Value;
8	use crate::project::Project;
9	use crate::session::Session;
10	
11	/// Runs the commands of this part.
12	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
13	    match cid {
14	        "sheet" => sheet(s, p),
15	        _ => place(s, p),
16	    }
17	}
18	
19	const UNNAMED: [&str; 9] = [
20	    "Unnamed",
21	    "Sem nome",
22	    "Sin nombre",
23	    "Namnlös",
24	    "Nepojmenovaný",
25	    "Sans nom",
26	    "Naamloos",
27	    "Unbenannt",
28	    "Senza nome",
29	];
30	
31	// ---------------------------------------------------------------- sheet
32	
33	fn sheet(s: &mut Session, p: &Value) -> R<Value> {
34	    let number = opt_text(p, "sheet", "number")?;
35	    let name = opt_text(p, "sheet", "name")?;
36	    let size = opt_text(p, "sheet", "size")?;
37	    let pr = &mut s.project;
38	    let number = match number {
39	        Some(n) => n,
40	        None => {
41	            let taken: Vec<String> = pr
42	                .elements
43	                .values()
44	                .filter(|e| cat(e) == "sheet")
45	                .filter_map(|e| s_of(e, "number").map(|x| x.to_string()))
46	                .collect();
47	            let mut n = 101u64;
48	            loop {
49	                let c = format!("A{}", n);
50	                if !taken.contains(&c) {
51	                    break c;
52	                }
53	                n += 1;
54	            }
55	        }
56	    };
57	    let name = name.unwrap_or_else(|| word(pr, UNNAMED).to_string());
58	    let size = match size {
59	        Some(x) => paper::normalize_size(&x),
60	        None => "A3".to_string(),
61	    };
62	    let id = pr.alloc_id();
63	    pr.elements.insert(
64	        id,
65	        jobj! {
66	            "guid" => crate::rand::guid(),
67	            "category" => "sheet",
68	            "number" => number.clone(),
69	            "name" => name,
70	            "size" => size,
71	        },
72	    );
73	    Ok(jobj! {"id" => id, "number" => number})
74	}
75	
76	// ---------------------------------------------------------------- place
77	
78	/// A number in degrees, as `place` reads `azimuth` and `elevation`.
79	fn opt_degrees(p: &Value, key: &str) -> R<Option<f64>> {
80	    match get(p, key) {
81	        None => Ok(None),
82	        Some(v) => mm_of(v)
83	            .map(Some)
84	            .ok_or_else(|| format!("place: `{}` must be a number in mm, got {}", key, v.to_compact())),
85	    }
86	}
87	
88	/// The sheet `place` puts the view on: by number, or by id.
89	fn find_sheet(pr: &Project, v: &Value) -> R<u64> {
90	    match v {
91	        Value::Str(s) => pr
92	            .elements
93	            .iter()
94	            .find(|(_, e)| cat(e) == "sheet" && s_of(e, "number") == Some(s.as_str()))
95	            .map(|(id, _)| *id)
96	            .ok_or_else(|| format!("place: no sheet numbered `{}`", s)),
97	        _ => {
98	            let not = || format!("place: `sheet`: {} is not a sheet", v.to_compact());
99	            let id = match v {
100	                Value::Num(_) => id_of(v).ok_or_else(not)?,
101	                _ => return Err(not()),
102	            };
103	            if cat_of(pr, id) == "sheet" {
104	                Ok(id)
105	            } else {
106	                Err(not())
107	            }
108	        }
109	    }
110	}
111	
112	/// What `place` takes: a view by id, or by name (a level's, a section's, an elevation's, a
113	/// schedule's or a 3D view's; a schedule of a category by its name in any language, made as it
114	/// is first placed; the 3D view by `{3D}`, made likewise). Some(id) of a view there, or the
115	/// schedule or 3D view to make.
116	enum Placed {
117	    Here(u64),
118	    NewSchedule(&'static str),
119	    New3D,
120	}
121	
122	const PLACEABLE: &[&str] = &["level", "planview", "section", "elevation", "schedule", "view3d"];
123	
124	fn find_placed(pr: &Project, v: &Value) -> R<Placed> {
125	    let not = || format!("place: `view`: {} is not a plan, a section, an elevation, a schedule or a 3D view", v.to_compact());
126	    match v {
127	        Value::Num(_) => {
128	            let id = id_of(v).ok_or_else(not)?;
129	            if PLACEABLE.contains(&cat_of(pr, id).as_str()) {
130	                Ok(Placed::Here(id))
131	            } else {
132	                Err(not())
133	            }
134	        }
135	        Value::Str(s) => {
136	            for (id, e) in &pr.elements {
137	                if PLACEABLE.contains(&cat(e)) && s_of(e, "name") == Some(s.as_str()) {
138	                    return Ok(Placed::Here(*id));
139	                }
140	            }
141	            if let Some(of) = paper::schedule_of(s) {
142	                let name = paper::schedule_name(pr, of);
143	                if let Some((id, _)) = pr
144	                    .elements
145	                    .iter()
146	                    .find(|(_, e)| cat(e) == "schedule" && s_of(e, "name") == Some(name.as_str()))
147	                {
148	                    return Ok(Placed::Here(*id));
149	                }
150	                return Ok(Placed::NewSchedule(of));
151	            }
152	            if s == DEFAULT_3D {
153	                return Ok(Placed::New3D);
154	            }
155	            Err(format!("place: no level, section, elevation, schedule or 3D view named `{}`", s))
156	        }
157	        _ => Err(not()),
158	    }
159	}
160	
161	/// The scale a view is drawn at: its template's where one controls it, its parent's for a
162	/// dependent plan, else its own, else 1 : 100.
163	pub fn scale_in_force(pr: &Project, view: u64) -> f64 {
164	    let Some(mut e) = pr.el(view) else { return 100.0 };
165	    if let Some(p) = ref_id(pr, e, "parent") {
166	        if let Some(pe) = pr.el(p) {
167	            e = pe;
168	        }
169	    }
170	    if let Some(t) = e.get("graphics").and_then(|g| s_of(g, "template")) {
171	        if let Some(name) = pr.lib_name(t) {
172	            if let Some(tp) = pr.section("view_templates").and_then(|v| v.get(&name)) {
173	                let controls = tp.get("controls").and_then(|c| c.as_arr());
174	                if controls.map_or(false, |c| c.iter().any(|x| x.as_str() == Some("scale"))) {
175	                    if let Some(sc) = tp.get("graphics").and_then(|g| f_of(g, "scale")) {
176	                        return sc;
177	                    }
178	                    if let Some(sc) = f_of(tp, "scale") {
179	                        return sc;
180	                    }
181	                }
182	            }
183	        }
184	    }
185	    e.get("graphics").and_then(|g| f_of(g, "scale")).unwrap_or(100.0)
186	}
187	
188	fn place(s: &mut Session, p: &Value) -> R<Value> {
189	    let pr = &mut s.project;
190	    let sheet = match get(p, "sheet") {
191	        None => return Err("place: `sheet`, a sheet's number or id, is required".into()),
192	        Some(v) => find_sheet(pr, v)?,
193	    };
194	    let scale = match get(p, "scale") {
195	        None => None,
196	        Some(v) => Some(mm_of(v).ok_or_else(|| format!("place: `scale` must be a number in mm, got {}", v.to_compact()))?),
197	    };
198	    let at = opt_point(p, "place", "at")?;
199	    let placed = match get(p, "view") {
200	        None => {
201	            return Err("place: `view`, a level's, section's, elevation's, schedule's or 3D view's name or id, is required".into())
202	        }
203	        Some(v) => find_placed(pr, v)?,
204	    };
205	    let is_3d = match &placed {
206	        Placed::New3D => true,
207	        Placed::Here(id) => cat_of(pr, *id) == "view3d",
208	        _ => false,
209	    };
210	    let (azimuth, elevation) = if is_3d {
211	        (opt_degrees(p, "azimuth")?, opt_degrees(p, "elevation")?)
212	    } else {
213	        (None, None)
214	    };
215	    let view = match placed {
216	        Placed::Here(id) => id,
217	        Placed::NewSchedule(of) => {
218	            let id = pr.alloc_id();
219	            let name = paper::schedule_name(pr, of);
220	            pr.elements.insert(
221	                id,
222	                jobj! {"guid" => crate::rand::guid(), "category" => "schedule", "name" => name, "of" => of},
223	            );
224	            id
225	        }
226	        Placed::New3D => {
227	            let id = ensure_default_3d(pr);
228	            let e = pr.el_mut(id).unwrap();
229	            if let Some(a) = azimuth {
230	                e.set("azimuth", Value::f(a));
231	            }
232	            if let Some(el) = elevation {
233	                e.set("elevation", Value::f(el));
234	            }
235	            id
236	        }
237	    };
238	    let scale = match scale {
239	        Some(x) => x,
240	        None => match cat_of(pr, view).as_str() {
241	            "level" | "planview" | "section" | "elevation" => scale_in_force(pr, view),
242	            _ => 100.0,
243	        },
244	    };
245	    let size = paper::view_size(pr, view, scale);
246	    let at = match at {
247	        Some(a) => a,
248	        None => paper::default_place(pr, sheet, size),
249	    };
250	    let id = pr.alloc_id();
251	    pr.elements.insert(
252	        id,
253	        jobj! {
254	            "guid" => crate::rand::guid(),
255	            "category" => "viewport",
256	            "sheet" => guid(pr, sheet),
257	            "view" => guid(pr, view),
258	            "at" => at,
259	            "scale" => scale,
260	        },
261	    );
262	    Ok(jobj! {"at" => at, "id" => id})
263	}
264	
265	// ---------------------------------------------------------------- the model's rules
266	
267	/// The model rules of this part, checked after every command (in `plans::views_check`).
268	pub fn check(pr: &Project) -> R<()> {
269	    let _ = pr;
270	    Ok(())
271	}
272	
273	/// What `elements` shows of this part's elements beyond their own fields: a sheet's paper and
274	/// the viewports on it; a viewport's size on the paper and its title.
275	pub fn element_view(pr: &Project, id: u64, x: &mut Value) {
276	    let Some(e) = pr.el(id) else { return };
277	    match cat(e) {
278	        "sheet" => {
279	            let (w, h) = paper::paper_size(s_of(e, "size").unwrap_or("A3")).unwrap_or((420.0, 297.0));
280	            x.set("paper", Value::from([w, h]));
281	            let g = guid(pr, id);
282	            let vps: Vec<Value> = pr
283	                .elements
284	                .iter()
285	                .filter(|(_, v)| cat(v) == "viewport" && s_of(v, "sheet") == Some(g.as_str()))
286	                .map(|(i, _)| Value::u(*i))
287	                .collect();
288	            x.set("viewports", Value::Arr(vps));
