1	//! Plans: `crop`, `duplicate_view` (plan views: duplicate, detailing, dependent); the rules of
2	//! every view and sheet; what goes with a view, a sheet or a level when it is deleted.
3	
4	pub mod shows;
5	
6	use super::common::*;
7	use super::model as m;
8	use crate::commands::params::{get, given, opt_text};
9	use crate::json::{Map, Value};
10	use crate::project::Project;
11	use crate::session::Session;
12	use std::collections::BTreeSet;
13	
14	/// Runs the commands of this part.
15	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
16	    match cid {
17	        "crop" => crop(s, p),
18	        _ => duplicate_view(s, p),
19	    }
20	}
21	
22	// ---------------------------------------------------------------- finding views
23	
24	/// A view by id, GUID or name, as `crop` and `duplicate_view` take one; `sheets` lets a sheet's
25	/// number name it. "`view`: X is not a view", "no view named `X`".
26	pub fn find_any_view(pr: &Project, cmd: &str, v: &Value, sheets: bool) -> R<u64> {
27	    let not = || format!("{}: `view`: {} is not a view", cmd, v.to_compact());
28	    match v {
29	        Value::Num(_) => {
30	            let id = id_of(v).ok_or_else(not)?;
31	            if pr.elements.contains_key(&id) {
32	                Ok(id)
33	            } else {
34	                Err(not())
35	            }
36	        }
37	        Value::Str(s) => {
38	            for (id, e) in &pr.elements {
39	                let c = cat(e);
40	                let named = if c == "sheet" {
41	                    sheets && s_of(e, "number") == Some(s.as_str())
42	                } else {
43	                    is_view_category(c) && s_of(e, "name") == Some(s.as_str())
44	                };
45	                if named {
46	                    return Ok(*id);
47	                }
48	            }
49	            if let Ok(id) = s.trim().parse::<u64>() {
50	                if pr.elements.contains_key(&id) {
51	                    return Ok(id);
52	                }
53	            }
54	            if let Some(g) = dashed_guid(s) {
55	                if let Some(id) = pr.find_guid(&g) {
56	                    return Ok(id);
57	                }
58	            }
59	            Err(format!("{}: no view named `{}`", cmd, s))
60	        }
61	        _ => Err(not()),
62	    }
63	}
64	
65	/// A GUID as a view is taken by: hyphenated, in any case, braced or not.
66	pub fn dashed_guid(s: &str) -> Option<String> {
67	    let t = s.trim();
68	    let t = t.strip_prefix('{').and_then(|x| x.strip_suffix('}')).unwrap_or(t);
69	    let b = t.as_bytes();
70	    if b.len() != 36 || [8, 13, 18, 23].iter().any(|&i| b[i] != b'-') {
71	        return None;
72	    }
73	    crate::model::normalize_guid(t)
74	}
75	
76	/// How a view is named in messages: its name, a sheet as "sheet A101".
77	fn what_view(pr: &Project, id: u64) -> String {
78	    match pr.el(id) {
79	        Some(e) if cat(e) == "sheet" => format!("sheet {}", s_of(e, "number").unwrap_or("")),
80	        Some(e) => match s_of(e, "name") {
81	            Some(n) => n.to_string(),
82	            None => cat_id(pr, id),
83	        },
84	        None => String::new(),
85	    }
86	}
87	
88	// ---------------------------------------------------------------- crop
89	
90	fn crop(s: &mut Session, p: &Value) -> R<Value> {
91	    const CMD: &str = "crop";
92	    // a crop is a step of its own even where the view was cropped so already
93	    super::mark_step();
94	    let pr = &mut s.project;
95	    let view = match get(p, "view") {
96	        Some(v) => find_any_view(pr, CMD, v, true)?,
97	        None => default_plan(pr).ok_or_else(|| format!("{}: the project has no level", CMD))?,
98	    };
99	    // the region: two corners, or null to uncrop; none, what the view shows
100	    let region: Option<Option<[[f64; 2]; 2]>> = if !given(p, "region") {
101	        None
102	    } else {
103	        match p.get("region").unwrap() {
104	            Value::Null => Some(None),
105	            Value::Arr(a) => {
106	                let mut pts = Vec::new();
107	                for q in a {
108	                    match crate::commands::params::point_of(q) {
109	                        Some(x) => pts.push(x),
110	                        None => {
111	                            return Err(format!("{}: `region`: {} is not a point [x, y] in mm", CMD, q.to_compact()))
112	                        }
113	                    }
114	                }
115	                if pts.len() != 2 {
116	                    return Err(format!("{}: `region` is two corners, [[x, y], [x, y]]", CMD));
117	                }
118	                Some(Some([pts[0], pts[1]]))
119	            }
120	            _ => return Err(format!("{}: `region` [[x, y], …] is required", CMD)),

