313	/// Each annotation category's fields in order, where `view` goes in a copy that has none.
314	fn annotation_order(c: &str) -> &'static [&'static str] {
315	    match c {
316	        "tag" => &["guid", "category", "host", "view", "offset", "leader", "label"],
317	        "dimension" => &[
318	            "guid", "category", "level", "view", "kind", "orient", "refs", "at", "type", "prefix", "suffix", "above", "below",
319	            "replace", "equality", "texts", "equal", "locked", "alignment",
320	        ],
