325	fn duplicate_view(s: &mut Session, p: &Value) -> R<Value> {
326	    const CMD: &str = "duplicate_view";
327	    let pr = &mut s.project;
328	    let view = match get(p, "view") {
329	        Some(v) => find_any_view(pr, CMD, v, false)?,
330	        None => default_plan(pr).ok_or_else(|| format!("{}: the project has no level", CMD))?,
331	    };
332	    let mode = match opt_text(p, CMD, "mode")? {
333	        None => "duplicate".to_string(),
334	        Some(m) => match m.as_str() {
335	            "duplicate" | "detailing" | "dependent" => m,
336	            _ => return Err(format!("{}: `mode` is duplicate, detailing or dependent, not `{}`", CMD, m)),
337	        },
338	    };
339	    let name = opt_text(p, CMD, "name")?;
340	    let c = cat_of(pr, view);
341	    if c != "level" && c != "planview" {
342	        return Err(format!(
343	            "{}: {} isn't a plan: plans are duplicated, sections, elevations, schedules, sheets and the 3D view not yet",
344	            CMD,
345	            what_view(pr, view)
346	        ));
347	    }
348	    let src = pr.el(view).unwrap().clone();
349	    if mode == "dependent" && src.get("parent").is_some() {
350	        return Err(format!(
351	            "{}: {} is a dependent view, which has none of its own: make it of its parent",
352	            CMD,
353	            what_view(pr, view)
354	        ));
355	    }
356	    let level = plan_level(pr, view).ok_or_else(|| format!("{}: {} has no level", CMD, what_view(pr, view)))?;
357	    let src_name = s_of(&src, "name").unwrap_or("").to_string();
358	    let name = match name {
359	        Some(n) => n,
360	        None => {
361	            let w = if mode == "dependent" { word(pr, DEPENDENT_WORD) } else { word(pr, COPY_WORD) };
362	            super::sections::numbered_name(pr, &format!("{} {}", src_name, w))
363	        }
364	    };
365	    let mut e = Map::new();
366	    e.insert("guid", Value::s(&crate::rand::guid()));
367	    e.insert("category", Value::s("planview"));
368	    e.insert("level", Value::s(&guid(pr, level)));
369	    e.insert("name", Value::s(&name));
370	    let vr = src.get("view_range").cloned().unwrap_or_else(|| {
371	        jobj! {"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0}
372	    });
373	    e.insert("view_range", vr);
374	    if let Some(c) = src.get("crop") {
375	        e.insert("crop", c.clone());
376	    }
377	    if mode == "dependent" {
378	        e.insert("parent", Value::s(&guid(pr, view)));
379	    } else {
380	        if let Some(g) = src.get("graphics") {
381	            e.insert("graphics", g.clone());
382	        }
383	        if let Some(b) = src.get("section_box") {
384	            e.insert("section_box", b.clone());
385	        }
386	    }
387	    let id = pr.alloc_id();
388	    let new_guid = s_of(&Value::Obj(e.clone()), "guid").unwrap().to_string();
389	    pr.elements.insert(id, Value::Obj(e));
390	    let mut copies = 0u64;
391	    if mode == "detailing" {
392	        let src_ids: Vec<u64> = pr
393	            .elements
394	            .iter()
395	            .filter(|(i, x)| **i != id && ANNOTATION.contains(&cat(x)) && in_view_own(pr, view, x))
396	            .map(|(i, _)| *i)
397	            .collect();
398	        for sid in src_ids {
399	            let mut x = pr.el(sid).unwrap().clone();
400	            x.set("guid", Value::s(&crate::rand::guid()));
401	            let ord = annotation_order(cat(&x));
402	            insert_in_order(&mut x, "view", Value::s(&new_guid), ord);
403	            renumber_parts(pr, &mut x);
404	            let nid = pr.alloc_id();
405	            pr.elements.insert(nid, x);
406	            copies += 1;
407	        }
408	    }
409	    Ok(jobj! {"annotations" => copies, "id" => id, "level" => level, "name" => name})
410	}
411	
412	/// Whether annotation is a view's own (not a dependent's parent's): by its `view`, or with none
413	/// a dimension or a tag on a level's own plan.
414	fn in_view_own(pr: &Project, view: u64, e: &Value) -> bool {
415	    let g = guid(pr, view);
416	    if let Some(v) = s_of(e, "view") {
417	        return v == g;
418	    }
419	    if cat_of(pr, view) != "level" {
420	        return false;
421	    }
422	    match cat(e) {
423	        "dimension" => s_of(e, "level") == Some(g.as_str()),
424	        "tag" => shows::host_level(pr, e).as_deref() == Some(g.as_str()),
425	        _ => false,
426	    }
427	}
428	
429	/// A copy's parts (a region's sketch lines…) get ids and GUIDs of their own.
430	fn renumber_parts(pr: &mut Project, x: &mut Value) {
431	    if let Some(Value::Arr(a)) = x.get_mut("sketch") {
432	        let n = a.len();
433	        let mut ids = Vec::new();
434	        for _ in 0..n {
435	            ids.push(pr.alloc_lib_id());
436	        }
437	        for (l, nid) in a.iter_mut().zip(ids) {
438	            if l.get("id").is_some() {
439	                l.set("id", Value::u(nid));
440	            }
441	            if l.get("guid").is_some() {
442	                l.set("guid", Value::s(&crate::rand::guid()));
443	            }
444	        }
445	    }
446	}
