10	
11	/// Runs the commands of this part.
12	pub fn run(s: &mut Session, cid: &str, p: &Value) -> R<Value> {
13	    match cid {
14	        "section" => section(s, p),
15	        _ => elevation(s, p),
16	    }
17	}
18	
19	// ---------------------------------------------------------------- names
20	
21	pub const SECTION_WORD: [&str; 9] = ["Section", "Corte", "Sección", "Sektion", "Řez", "Coupe", "Doorsnede", "Schnitt", "Sezione"];
22	pub const ELEVATION_WORD: [&str; 9] = ["Elevation", "Elevação", "Elevación", "Fasad", "Pohled", "Élévation", "Gevel", "Ansicht", "Prospetto"];
23	const NORTH: [&str; 9] = ["North", "Norte", "Norte", "Norr", "Sever", "Nord", "Noord", "Norden", "Nord"];
24	const SOUTH: [&str; 9] = ["South", "Sul", "Sur", "Söder", "Jih", "Sud", "Zuid", "Süden", "Sud"];
25	const EAST: [&str; 9] = ["East", "Leste", "Este", "Öster", "Východ", "Est", "Oost", "Osten", "Est"];
26	const WEST: [&str; 9] = ["West", "Oeste", "Oeste", "Väster", "Západ", "Ouest", "West", "Westen", "Ovest"];
27	
28	/// The categories whose names are views' names, which no two may share.
29	pub const NAMED_VIEWS: &[&str] = &["planview", "section", "elevation", "view3d", "schedule"];
30	
31	/// Every name a view (or a level) goes by.
32	pub fn taken_names(pr: &Project) -> Vec<String> {
33	    pr.elements
34	        .values()
35	        .filter(|e| NAMED_VIEWS.contains(&cat(e)) || cat(e) == "level")
36	        .filter_map(|e| s_of(e, "name").map(|s| s.to_string()))
37	        .collect()
38	}
39	
40	/// `<word> n`, the first n no view has.
41	pub fn numbered_name(pr: &Project, word: &str) -> String {
42	    let taken = taken_names(pr);
43	    let mut n = 1u64;
44	    loop {
45	        let c = format!("{} {}", word, n);
46	        if !taken.contains(&c) {
47	            return c;
48	        }
49	        n += 1;
50	    }
51	}
52	
53	/// The word itself where no view has it, else `<word> 2`, `<word> 3`…
54	pub fn word_name(pr: &Project, word: &str) -> String {
55	    let taken = taken_names(pr);
56	    if !taken.iter().any(|t| t == word) {
57	        return word.to_string();
58	    }
59	    let mut n = 2u64;
60	    loop {
61	        let c = format!("{} {}", word, n);
62	        if !taken.contains(&c) {
63	            return c;
64	        }
65	        n += 1;
66	    }
67	}
