71	fn section(s: &mut Session, p: &Value) -> R<Value> {
72	    let start = req_point(p, "section", "start")?;
73	    let end = req_point(p, "section", "end")?;
74	    let depth = opt_num(p, "section", "depth")?;
75	    let name = opt_text(p, "section", "name")?;
76	    let pr = &mut s.project;
77	    let name = match name {
78	        Some(n) => n,
79	        None => numbered_name(pr, word(pr, SECTION_WORD)),
80	    };

