import math, itertools
P = [(0.0, 0.0), (7071.0678, 7071.0678), (2828.4271, 11313.7085), (-4242.6407, 4242.6407)]
h = 100.0
def sub(a, b): return (a[0] - b[0], a[1] - b[1])
def add(a, b): return (a[0] + b[0], a[1] + b[1])
def mul(a, k): return (a[0] * k, a[1] * k)
def cross(a, b): return a[0] * b[1] - a[1] * b[0]
def nrm(a): return math.sqrt(a[0] * a[0] + a[1] * a[1])
def udiv(a):
    l = nrm(a); return (a[0] / l, a[1] / l)
def uinv(a):
    l = nrm(a); r = 1 / l; return (a[0] * r, a[1] * r)
# targets per corner for the outer (right) face mitre point: (axis, value)
targets = {0: ('y', -141.421356237309), 1: ('x', 7212.48915623731), 2: ('y', 11455.129856237309), 3: ('x', -4384.06205623731)}
walls = [(P[i], P[(i + 1) % 4]) for i in range(4)]
def run(order, unit, form, anchor_mode):
    # right faces as [start, end] points, direct
    faces = []
    for s, e in walls:
        u = unit(sub(e, s)); n = (-u[1], u[0])
        faces.append([add(s, mul(n, -h)), add(e, mul(n, -h))])
    res = {}
    for k in order:
        a = (k - 1) % 4; b = k  # wall a ends at corner k, wall b starts there
        p1, p2 = faces[a]; q1, q2 = faces[b]
        if form == 'pts':
            r = sub(p2, p1); s_ = sub(q2, q1)
            pa = p1 if anchor_mode[0] == 's' else p2
            qa = q1 if anchor_mode[1] == 's' else q2
        else:
            ua = unit(sub(walls[a][1], walls[a][0])); ub = unit(sub(walls[b][1], walls[b][0]))
            r = ua; s_ = ub
            pa = p1 if anchor_mode[0] == 's' else p2
            qa = q1 if anchor_mode[1] == 's' else q2
        t = cross(sub(qa, pa), s_) / cross(r, s_)
        M = add(pa, mul(r, t))
        faces[a][1] = M; faces[b][0] = M
        res[k] = M
    ok = 0
    for k, (ax, v) in targets.items():
        val = res[k][0] if ax == 'x' else res[k][1]
        ok += (val == v)
    return ok, res
best = []
for order in itertools.permutations(range(4)):
    for un, unit in [('div', udiv), ('inv', uinv)]:
        for form in ['pts', 'unit']:
            for am in ['ss', 'se', 'es', 'ee']:
                ok, res = run(order, unit, form, am)
                best.append((ok, order, un, form, am))
best.sort(reverse=True)
for b in best[:10]: print(b)

